pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by capacity fractions (integer division)
    let item_class = item_size / (bin_capacity / 4); // 0..=4 coarse class
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / (bin_capacity / 4) };

    // Reward tight fits: small post_residual is good
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Penalize dead space that no small item can use: post_residual classes
    // Class boundaries: post_residual < 10 unusable-ish; 10..=20 marginal; >20 reusable
    if post_residual > 0 && post_residual < 10 {
        score += 35.0; // nearly dead space
    } else if post_residual <= 20 {
        score += 10.0; // marginal
    } else {
        // reusable residual: reward proportionally, especially if next item fits
        score -= 8.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // lookahead: next item slots perfectly here
        }
    }

    // Harmonic pairing: reward when post_residual mod small-item granularity aligns
    // with next item class (e.g., residual 50 pairs with item 50, 25, 20...)
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_res = post_residual - next_item_size;
        if pair_res < 10 {
            score -= 20.0; // chain leaves another near-tight fit
        } else if pair_res == 0 {
            score -= 45.0; // perfect chain fill
        }
    }

    // Penalize mismatched classes: huge item into a mostly-empty bin wastes it
    if item_class >= 3 && post_residual > 30 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Many fitting bins: prefer the tightest anyway (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when open bins would be badly fragmented
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / (bin_capacity as f64);
        // Open a new bin when existing residuals are small and item is large
        if item_size > 50 && avg_fragmentation < 0.35 {
            score -= 55.0;
        } else {
            score += 25.0; // default: prefer existing bins
        }
        if next_item_size > 0 && next_item_size > 60 {
            score -= 15.0; // save fresh bins for the big next item too
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Mean residual coupling: if mean residual is high, tighter-than-mean fits are better
    score += 0.3 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mean_norm = mean_residual / cap;
    let nf = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let quarter = (bin_capacity / 4).max(1);
    let item_class = item_size / quarter;

    // Base: wasted space with super-linear punishment of large residuals.
    let mut score = pr + 14.0 * norm_pr * norm_pr * cap;

    // Progress-coupled residual pressure.
    let pp = 0.5 + progress * progress * 1.5;
    score += 30.0 * pp * norm_pr * (1.0 - norm_pr);

    // Smooth reward for near-perfect fits.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chaining with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = nf / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let leftover_after = post_residual - next_item_size;
            if leftover_after <= 2 {
                score -= 25.0;
            } else if leftover_after <= 6 {
                score -= 8.0 * (1.0 - (leftover_after - 2) as f64 / 4.0);
            }
            if leftover_after > 0 && (leftover_after as f64) < 0.5 * nf {
                score += 4.0 * (1.0 - leftover_after as f64 / nf);
            }
            // divisibility chain reward
            if leftover_after > 0 && next_item_size > 1 && leftover_after % next_item_size == 0 {
                score -= 7.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / nf.max(1.0);
            score += 8.0 * norm_pr * (0.3 + progress) + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
            // stranded dead-space refinement
            if gap > nf * 0.4 && gap < mean_residual * 0.8 {
                score += 8.0 * (1.0 - gap / (mean_residual * 0.8)) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Mean-residual coupling: below-mean bins are compact.
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Dead-space ratio penalty when next item cannot follow.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        if norm_pr > 0.22 {
            score += 32.0 * (norm_pr - 0.22) * (0.5 + progress) * (1.0 + mean_norm);
        }
        let dead_frac = 1.0 - pr / nf;
        score += 10.0 * dead_frac * dead_frac * (0.4 + progress);
    }

    // Multi-fit competition.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 {
        let mismatch = (pr - nf).abs() / cap;
        let comp = ((fitting_bins_count - 1) as f64).ln().max(0.0);
        score += 6.0 * mismatch * comp;
        if pr == nf {
            score -= 5.0 * comp;
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Exact-fill chain reward.
    if !is_new_bin && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) <= mean_residual * 0.35 {
            score -= 12.0 * (1.0 - after as f64 / (mean_residual * 0.35).max(1.0)) * (0.5 + progress);
        }
    }

    // Compaction pull — reward near-zero post-residual after hosting next item.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
