    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;

    // Dead-space penalty: residuals in awkward bands (just above quarter / half marks)
    let rem_q = post_residual % (bin_capacity / 4).max(1);
    if rem_q > 0 && rem_q < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Reward residuals that are harmonic with common item sizes (multiples of 10)
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Integer-division threshold: classify post_residual into capacity-fraction classes
    let class = post_residual / (bin_capacity / 10).max(1); // 0..10 decile
    score += class as f64 * 2.0;

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus, scaled by how well it chains (modulo harmony)
            score -= 20.0;
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here; penalize less if residual still large
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets baseline anchored to mean residual
    if bin_residual == bin_capacity {
        // prefer new bin only if it beats wasting space in open bins
        score = c * 0.5 + mean_residual * 0.5 - pr * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // late in stream, discourage opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

