    // Smooth non-linear coupling: post-residual cost modulated by stream progress.
    // Early in the stream, waste matters less (bins can be filled later);
    // late in the stream, dead space becomes increasingly expensive.
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 8.0 * progress_weight * norm_pr * norm_pr * cap;

    // Non-linear penalty for small residuals that are unlikely to be usable,
    // scaled by how full the stream is.
    let unusability = (-norm_pr * 10.0).exp(); // large when post_residual near 0
    score += 4.0 * progress * unusability;

    // Reward tight fits: item fills most of the bin.
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits into the post residual, reward it smoothly.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let margin = (post_residual as f64 - next_item_size as f64) / cap;
        let smooth_fit = fits_next * (-margin * margin * 20.0).exp();
        score -= 5.0 * smooth_fit * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open and this placement keeps residual fragmented.
    let frag = (mean_residual - pr).abs() / cap;
    score += 2.0 * frag * frag * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: penalize opening a new bin unless current bin would be left
    // with unusable space or stream is early and bins are scarce.
