            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 8.0 * (1.0 - slack / cap); // tighter lookahead fit is better
            }
        } else {
            // next item won't fit here; mild penalty scaled by how much dead space remains
            score += 4.0 + (post_residual as f64) / 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when current fit is bad
    // or the item perfectly fills a fresh bin.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 50.0; // item == capacity, must open new bin
        } else if post_residual <= 10 {
            score -= 5.0;
        } else {
            score += 18.0; // discourage wasting a fresh bin on a sloppy fit
        }
