    // Stream-phase modulation: early on, keep bins tidy (penalize large residuals);
    // late in the stream, prefer consolidation into existing bins.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (mean_residual - post_residual as f64) * 0.15;

