    if is_new_bin && next_item_size > 0 {
        if next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // ---- Last-chance bonus: if this is the ONLY fitting bin, strongly prefer using it ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // ---- Penalize opening new bins when decent open bins exist ----
    if is_new_bin {
        // New-bin base handicap grows with number of open bins and mean available space
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 + 5.0 * open_pressure;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0; // plenty of room already open; discourage spreading
        }
        // Early in the stream, be more willing to open bins (build diversity)
        score -= 15.0 * (1.0 - progress);
    }

    // ---- Tight-fit reward: placing item leaving very small residual is excellent ----
    if !is_new_bin {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // ---- Global state: many open bins with high mean residual -> consolidate, don't fragment ----
    if !is_new_bin && mean_residual > 30.0 && open_bins_count > 3 {
        score += 3.0; // slight push toward bins below-average residual (tighter bins)
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // ---- Late-stream conservatism: avoid tiny useless slivers near the end ----
    if !is_new_bin && post_residual < 10 {
        score -= 8.0; // slivers under 10 are dead weight; using them up is great
    }

    // Small deterministic tie-breaker spread by bin residual
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, clamped to [0,1]
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Smooth non-linear coupling: residual value changes with progress.
    // Early on, large residuals are fine; late, we penalize them quadratically.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let progress_coupling = pr_norm * (0.5 + 1.5 * progress * progress);
    score += 40.0 * progress_coupling;

    // Perfect-fit reward: smooth polynomial in post_residual
    let fit_bonus = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 25.0 * fit_bonus * (1.0 + 0.5 * progress);

    // Last-chance bin: reward smoothly with progress
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * progress);
    }

    // Dead-space penalty: unusable space (post_residual < next item)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let waste = pr / nxt;
            score += 30.0 * waste * waste;
        }
        // Reward bins where the next item also fits (smooth chaining bonus)
        if nxt <= pr {
            let chain = 1.0 - pr / (pr + nxt);
            score -= 10.0 * chain * (1.0 - progress);
        }
    }

    // Mild pressure from many open bins vs mean residual
    let mr = mean_residual / bin_capacity as f64;
    score += (open_bins_count as f64).ln() * mr * (2.0 + 4.0 * progress);

    // Penalize new-bin candidate slightly unless residual is tiny elsewhere
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in the same "octave"
    // (cap/8 bands) are equally usable; reward tight fits.
    let band = (post_residual * 8 + bin_capacity - 1) / bin_capacity; // 0..8
    score -= (8 - band) as f64 * 2.0;

    // Exact-fit classes via integer division thresholds
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 20.0; // near-perfect: dead space small enough to be ignorable
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0; // round residuals pair well with typical item sizes
    }

    // Penalize residuals that no plausible future item (1..100) can use well:
    // residual < smallest useful chunk is dead space unless 0.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            // harmonic class of the double placement
            if new_post <= 5 {
                score -= 25.0;
            } else {
                score -= (post_residual - new_post) as f64 * 0.1;
            }
        } else {
            // next item won't fit here: residual must stay attractive for others
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin for a bad fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(1.0);
        let mean_tightness = 1.0 - mean_residual / cap;
        let poor_fit = if post_residual < 20 { 1.0 } else { 0.0 };
        score = cap - 35.0 * mean_tightness - 10.0 * poor_fit + crowding;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits: new bin mandatory
        }
        if next_item_size > 0 && next_item_size <= post_residual / 2 {
            score += 10.0; // don't waste a fresh bin when lookahead also fits elsewhere
        }
    }

    // Mild stream-phase modulation: early on, keep bins flexible (favor
    // larger residuals less aggressively); late in stream, close bins out.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * (post_residual as f64) * 0.15;

    // Coupling with mean residual: bins far below mean are "underfilled";
    // prefer filling them to balance the portfolio.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=12) are heavily penalized,
    // since nothing else in the stream can ever fill them.
    if post_residual >= 1 && post_residual <= 12 {
        score += 45.0 * (13.0 - post_residual as f64) / 13.0;
    }

    // Reward very tight fits (near-perfect packing) with a strong discount.
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 8.0;
    }

    // Prefer bins whose residual was already small (compact bins over loose ones).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Open-bin pressure: discourage spreading across many bins when few bins fit
    // the item (last-chance bins are precious), and encourage consolidation.
    if fitting_bins_count <= 2 {
        score -= 6.0 * fitting_bins_count as f64;
    } else {
        score -= 2.0;
    }
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if open bins are generally loose, prefer filling
    // an existing bin; if they are tight, tolerate opening a new one.
    score += 0.05 * mean_residual;

    // Lookahead: if the next item would fit exactly in the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.3 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; small penalty for leaving a gap
        // that the next item cannot use.
        score += 3.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open
    // bin fits well (post_residual of a fresh bin is large, so this mostly
    // matters for the dead-space logic). Penalize opening new bins early in
    // the stream and when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual <= 30 {
            score += 12.0; // an open bin leaves a usable gap; don't open a new one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's post residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // chain both items into this bin
        } else if post_residual >= next_item_size {
            // next item still fits here afterwards: mild bonus proportional to slack left
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit after placement: penalize wasted potential
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Tight fit now is good (small post residual), but keep some usability.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Compare against mean residual of open bins: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: penalize unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 120.0; // packing a pair into a fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in stream -> more conservative, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: exact fit gets big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space proportionally to how unusable it is.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 40.0;
    }

    // Last-chance bin: strongly favor using it, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, mild preference for tighter ones.
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by how snug.
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * snug;
        } else {
            // next item cannot use the leftover: penalize large leftovers slightly.
            score += 6.0;
        }
    } else {
        // Last item: exact fill is all that matters.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Global state: many open bins with high mean residual -> avoid fragmenting further.
    if open_bins_count > 0 {
        let crowding = open_bins_count as f64;
        score += 0.3 * crowding * (1.0 - (bin_residual as f64 / bin_capacity as f64));
        // If this bin's residual is above mean residual, it's roomier than average: favor using it.
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.2 * diff;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it's only chosen
    // when all open bins look bad (their scores pushed high by dead-space/crowding terms).
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
        // Opening a new bin is cheaper when few bins are open.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early stream, be slightly exploratory (favor new bins for large items
    // that would leave awkward residue); late stream, squeeze everything in.
    if progress < 0.3 && item_size <= 30 && post_residual > 50 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for large dead space (cubic in normalized residual)
    score += 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: smooth interaction between post_residual and item size
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (item_size as f64 / cap);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize bins whose residual deviates far from the mean (imbalance)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead coupling: reward bins whose post-residual can host the next item smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 10.0 * (ni - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_tight = 1.0 - mean_residual / cap;
        score += 45.0 - 40.0 * avg_tight * avg_tight + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by capacity fractions (integer division)
    let item_class = item_size / (bin_capacity / 4); // 0..=4 coarse class
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / (bin_capacity / 4) };

    // Reward tight fits: small post_residual is good
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Penalize dead space that no small item can use: post_residual classes
    // Class boundaries: post_residual < 10 unusable-ish; 10..=20 marginal; >20 reusable
    if post_residual > 0 && post_residual < 10 {
        score += 35.0; // nearly dead space
    } else if post_residual <= 20 {
        score += 10.0; // marginal
    } else {
        // reusable residual: reward proportionally, especially if next item fits
        score -= 8.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // lookahead: next item slots perfectly here
        }
    }

    // Harmonic pairing: reward when post_residual mod small-item granularity aligns
    // with next item class (e.g., residual 50 pairs with item 50, 25, 20...)
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_res = post_residual - next_item_size;
        if pair_res < 10 {
            score -= 20.0; // chain leaves another near-tight fit
        } else if pair_res == 0 {
            score -= 45.0; // perfect chain fill
        }
    }

    // Penalize mismatched classes: huge item into a mostly-empty bin wastes it
    if item_class >= 3 && post_residual > 30 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Many fitting bins: prefer the tightest anyway (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when open bins would be badly fragmented
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / (bin_capacity as f64);
        // Open a new bin when existing residuals are small and item is large
        if item_size > 50 && avg_fragmentation < 0.35 {
            score -= 55.0;
        } else {
            score += 25.0; // default: prefer existing bins
        }
        if next_item_size > 0 && next_item_size > 60 {
            score -= 15.0; // save fresh bins for the big next item too
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Mean residual coupling: if mean residual is high, tighter-than-mean fits are better
    score += 0.3 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to ever fit a future item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: waste ratio scaling.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when open count is low,
    // but when many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 30.0 + open_bins_count as f64 * 3.0 + progress * 20.0;
    } else {
        // Slight reward for using existing bins when many are open.
        score -= (open_bins_count as f64).min(20.0) * 0.8;
    }

    // Mean-residual coupling: prefer bins below mean residual (filling emptier bins first
    // keeps larger residuals concentrated).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: minimal dead space
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that is unlikely to be reused
        let min_item = 1u32;
        if post_residual < min_item {
            score += 500.0;
        }
        // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strongly favor
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 800.0;
            } else if next_item_size < post_residual {
                // next item fits: reward tight coupling, penalize wasted slack
                let slack = (post_residual - next_item_size) as f64;
                score -= 200.0 - 2.0 * slack;
            } else {
                // next item does NOT fit here: penalize bins whose residual is just below next size
                let gap = (next_item_size - post_residual) as f64;
                score += gap * 3.0;
            }
        }

        // Relative residual vs mean residual: prefer tighter-than-average bins
        score += (post_residual as f64 - mean_residual) * 1.5;
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless nothing fits well
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 120.0;
        // if next item is large and current item small, new bin may be better
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 60.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
    }

    // Mild penalty for very fragmented open-bin pools
    if open_bins_count > 20 {
        score += (open_bins_count as f64 - 20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0; // still reusable by small items
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // If next item would leave this bin's residual stranded, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized when good fits exist,
    // rewarded when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Open new bin if existing residuals are large (items fit poorly) or late in stream.
        score = 40.0 - 30.0 * fragmentation + 20.0 * progress;
