}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual). Late stream: tolerate larger post_residual
    // because closing out bins matters more than future flexibility.
    let t = progress;
    let poly = pr * (1.0 + 0.6 * t * t) - 0.35 * pr * pr / cap * t;

    // Reward near-perfect fills: quadratic bonus as post_residual approaches 0.
    let tight_bonus = -(1.0 - pr / cap).powf(3.0) * 8.0;

    // Lookahead coupling: penalize post_residual that cannot host the next item.
    let next_pen = if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n { -0.5 * (1.0 - n / cap) } else { 0.4 * (n - pr) / cap }
    } else { 0.0 };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // Fragmentation penalty relative to mean residual across open bins.
    let frag = 0.3 * (pr - mean_residual) / cap;

    // Slight penalty for spreading across many bins late in the stream.
    let spread = 0.05 * (open_bins_count as f64) * t;

    poly + tight_bonus + next_pen + last_chance + frag + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;

