    // New-bin candidate handling: empty bin gets neutral-ish score; make it attractive
    // only when existing fits are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score = pr * (1.0 + 0.8 * x * x) + 4.0 - 6.0 * (1.0 - progress);
