    }

    // Tight fit now is good, but keep some usability: convex quadratic on post residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 22.0;

    // Compare against mean residual of open bins: prefer bins tighter than average,
    // with a slightly stronger pull late in the stream.
    score += (post_residual as f64 - mean_residual) * (0.45 + 0.25 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
