            if post_residual - next_item_size <= 2 {
                score -= 25.0;
            }
            // near-perfect chain: post residual is within a small window of next item
            if post_residual - next_item_size <= 8 {
                score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / 8.0);
            }
        } else {
            // next item won't fit after placement: penalize wasted potential,
            // but soften the penalty when the gap is small (item may shrink-fit later)
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + gap * 0.35;
            if gap <= 6.0 {
                score -= 8.0; // borderline miss: don't over-punish
            }
        }
    }

    // Tight fit now is good (small post residual), but keep some usability.
    // Dead-space shaping: strongly discourage residual bands that are hard to fill
    // (very small leftovers that no typical item can use).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 22.0;
    if post_residual > 0 && post_residual < 10 {
        score += 14.0 * (10 - post_residual) as f64 / 10.0; // tiny dead space is nearly worthless
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.55;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
        // even stronger late in the stream where new bins hurt most
        score -= 25.0 * progress;
    }

    // New empty bin candidate: penalize unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 170.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 130.0; // packing a pair into a fresh bin is fine
            // triple lookahead: fresh bin fits a pair AND leaves room for next-next sizes
            if item_size + next_item_size + 10 <= bin_capacity {
                score -= 15.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 220.0;
        }
        // opening a fresh bin is more acceptable early on; late stream, resist it
        score += 60.0 * progress;
    }

    // Late in stream, prefer consolidating into existing bins.
    score *= 1.0 - 0.18 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never fit a plausible future item:
    // post_residual below the minimum item size is pure waste.
    if post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement;
    // if the next item would no longer fit here but fits elsewhere, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * chain_fit;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer spreading items,
    // keep residuals flexible); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state coupling: when mean residual across open bins is high, favor
    // filling existing bins harder (reduce fragmentation); when low, mild new-bin tolerance.
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score -= 5.0 * mean_res_norm * tightness;
    score += 4.0 * (1.0 - mean_res_norm) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation to limit bin count growth.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // New-bin candidate: make it moderately attractive only when the item fits
    // poorly in residual terms elsewhere (handled by competition) — baseline
    // slight penalty so we don't open bins too eagerly, but allow it when
    // item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score -= 2.0 + 10.0 * large_item * (1.0 - open_pressure);
        // Late in stream, opening new bins is cheap since stream ends soon.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
