        4 => 2.5,
        _ => 3.0,
    };

    // Perfect-fit harmonic bonus: post_residual exactly divisible into
    // expected future chunks (multiples of 10 or 20).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack % 20 == 0 {
            score -= 4.0;
        } else if slack % 10 == 0 {
            score -= 2.0;
        }
    }

    // Prefer tighter bins (residual below mean) to consolidate waste.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: prefer reusing open bins by default,
