        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            // Prefer fresh bins whose pair leaves a residual close to common
            // item sizes (higher chance the leftover gets reused).
            let reuse = (1.0 - (leftover - mean_residual).abs() / cap).max(0.0);
            score -= 15.0 * reuse * (1.0 - progress);
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        // If no open bin fits at all, opening a new bin is mandatory.
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes are preferred (leftover reusable by small items).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward: strong subtraction.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Fraction-of-capacity classes: leftover in [1..10] is dead space (penalize),
    // leftover in [10..30] is reusable by small items (reward).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 25.0; // sweet-spot leftover
    }

    // Modulo arithmetic on post_residual: leftover divisible by common item
    // sizes (10, 20, 25) is likely to be filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Coupling with lookahead: if next item fits exactly in the leftover,
    // this bin becomes a two-step perfect fit — heavily favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 40.0;
            if rem2 % 10 == 0 {
                score -= 20.0;
            }
            if rem2 == 0 {
                score -= 200.0;
            }
        } else {
            // next item cannot use leftover: leftover risk grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Integer-division thresholds: leftover that could host a mid-size item
    // (>= 25) is more valuable than leftover hosting only tiny items.
    let mid_fits = post_residual / 25;
    score -= mid_fits as f64 * 12.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists. Scale pressure with number of open bins.
    if bin_residual == bin_capacity {
        let base = 120.0 + 8.0 * open_bins_count as f64;
        // Opening a bin is attractive if the item nearly fills it and would
        // otherwise leave bad residue elsewhere.
        let tightness = item_size as f64 / cap;
        score = base - tightness * 100.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    // Slight global pressure: keep mean residual low by preferring bins below
    // the mean (they are closer to being closed out).
    let dev = mean_residual - pr;
    score += dev * 0.3;

    // Late-stream tie-breaking: prefer tighter fills as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
