            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Dead space the next item can't use: penalize proportionally.
            score += 0.25 * (post_residual as f64);
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs() / (bin_capacity as f64);
        // Prefer new bin when item is big and mean residual is small (poor fits elsewhere)
        let open_pressure = 1.0 / (open_bins_count as f64 + 1.0);
