            - 20.0 * open_pressure
            - 10.0 * fragmentation
            - 8.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
        // If only a few bins fit the item, opening new is less attractive.
        if fitting_bins_count <= 2 {
            score += 15.0;
        }
    }

    // Mild penalty for wasting space relative to the mean residual across bins.
    score += 0.05 * ((post_residual as f64) - mean_residual).max(0.0);

    // Slight preference to balance residuals early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space with super-linear penalty on large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Progress-coupled slack penalty: tolerate slack early, punish late.
    let pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * pressure * norm_pr * (1.0 - norm_pr);

    // Smooth reward for near-perfect fits, sharpened late.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chain logic against next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let pair_res = post_residual - next_item_size;
            if pair_res <= 2 {
                score -= 25.0;
            } else if pair_res <= 6 {
                score -= 8.0 * (1.0 - (pair_res - 2) as f64 / 4.0);
            }
            // Harmonic-style: leftover after pair reusable by small items.
            if pair_res >= 10 && pair_res <= 30 {
                score -= 6.0;
            }
            // NEW: dead-space ratio of pair leftover — punish unusable slivers.
            let pair_dead = pair_res as f64 / pr.max(1.0);
            if pair_res > 6 {
                score += 14.0 * pair_dead * pair_dead * (0.4 + progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Mean residual coupling: below-mean residuals are compact, above-mean penalized.
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Last-chance bin: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -10.0;
        } else {
            let open_pressure = (open_bins_count as f64).ln().max(0.0);
            score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);

            // Fresh-bin pair planning: large item + compatible next item early is OK.
            if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                let leftover = (bin_capacity - item_size - next_item_size) as f64;
                score -= 60.0 * (1.0 - progress)
                    + 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            }

            // Large item with badly fragmented open bins: fresh bin is attractive.
            let avg_fragmentation = mean_residual / cap;
            if item_size > 50 && avg_fragmentation < 0.35 && progress < 0.6 {
                score -= 30.0;
            }

            // NEW: mid-stream fresh-bin pair quality — exact pair fit makes a fresh
            // bin very attractive even slightly later in the stream.
            if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.85 {
                score -= 35.0;
            }

            // Late-stream: opening new bins is expensive.
            if progress > 0.6 {
                score += 45.0 * (progress - 0.6) / 0.4;
            }
