    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual matches the item well (tight fit).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual availability.
        score += 40.0 + 10.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        if mean_residual >= item_size as f64 {
            score += 30.0; // an existing bin could take it
        }
    } else {
        score -= 3.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Penalize if next item almost fits but would leave the residual stranded.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Tight-fit bump, sharpened by progress
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Chain lookahead: exact / near / partial matches
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let rem = post_residual - next_item_size;
            if rem <= 2 {
                score -= 25.0;
            } else if rem <= 6 {
                score -= 8.0 * (1.0 - (rem - 2) as f64 / 4.0);
            } else if rem >= 10 {
                // chain leaves a reusable residual that could host the item after next
                score -= 6.0 * (1.0 - rem as f64 / cap);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress) + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Mean-residual coupling
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: pressure-aware attractiveness
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
        }
        // Big item into fragmented open bins: fresh bin attractive
        let avg_fragmentation = mean_residual / cap;
        if item_size > 50 && avg_fragmentation < 0.35 {
            score -= 35.0;
        }
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation scale
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (smallest post_residual), with slight smoothing.
    score = post_residual as f64 * 1.0;

    // Reward exact/near-exact fits.
    if post_residual == 0 {
