    // post-residual, this bin is a perfect two-item chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits; reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: leaving a residual that cannot
            // host the next item is dead space -> penalize mildly.
            score += 8.0;
