    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 + 20.0 * pressure + 3.0 * crowding;
        // Late in the stream, opening new bins is especially wasteful.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * t;
    } else {
        // Slight preference for reusing bins as the stream progresses.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * t;
    }

    // Coupling: if this bin's residual deviates strongly above mean residual, it's an outlier
    // worth filling (large leftover bins should be consumed first).
