    // If the next item exactly fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward if next item can still fit, scaled by how well it uses the leftover.
        let next_use = next_item_size as f64 / post;
        score -= 8.0 * next_use * next_use;
    } else if next_item_size > 0 {
        // Penalize residuals that the next item cannot use at all.
        score += 6.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // New-bin candidate: neutral baseline; open a new bin only when all open bins
    // are crowded (mean residual low) or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
