}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space with mild super-linear penalty on large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Progress-coupled slack penalty: tolerate slack early, punish late.
    let pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * pressure * norm_pr * (1.0 - norm_pr);

    // Smooth reward for near-perfect fits.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chain logic against next item (combined with fine-grained fitting).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fill * (1.0 - norm_pr);
            let pair_res = post_residual - next_item_size;
            if pair_res == 0 {
                score -= 30.0;
            } else if pair_res <= 2 {
                score -= 25.0;
            } else if pair_res <= 6 {
                score -= 8.0 * (1.0 - (pair_res - 2) as f64 / 4.0);
            }
            // Harmonic-style: reward when leftover after pair is reusable by small items
            if pair_res >= 10 && pair_res <= 30 {
                score -= 6.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
