        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -10.0;
        } else {
            let open_pressure = (open_bins_count as f64).ln().max(0.0);
            score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);

            // Fresh-bin pair planning: putting a large item with a compatible next item
            // into a fresh bin is acceptable early.
