pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits into post_residual with small slack -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize residuals too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Tight fits are valuable: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize bins whose residual deviates strongly from the mean (imbalance).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: give it a baseline cost so it is only chosen when clearly better.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item is huge and nothing fits well, opening a new bin is fine.
        if next_item_size > 0 && post_residual == 0 {
            score -= 40.0;
        }
    }

    // Late in stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
