            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next <= 2 {
                score -= 25.0 + 15.0 * progress;
            } else if leftover_after_next <= 6 {
                // near-chain match: mild extra reward to reduce dead space
                score -= 8.0 * (1.0 - (leftover_after_next - 2) as f64 / 4.0);
            } else {
                // leftover after the pair is still usable by typical items:
                // mild reward proportional to its usability
                let usable = (leftover_after_next as f64 / 100.0).min(1.0);
                score -= 6.0 * usable * (1.0 - progress);
            }
            // Two-step lookahead: if the pair's leftover would exactly chain
            // with a small item, this bin is a great compaction target.
            if leftover_after_next >= 1 && leftover_after_next <= 30 && progress < 0.85 {
                score -= 10.0 * (1.0 - leftover_after_next as f64 / 30.0);
            }
        } else {
            // Dead space that next item cannot use: smooth penalty, sharpened
            // when the gap is large relative to the residual (true dead space).
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
