        if next_item_size > 0 && fitting_bins_count > 0 && progress < 0.6 {
            let chains_perfectly = bin_capacity >= item_size + next_item_size
                && (bin_capacity - item_size - next_item_size) <= 2;
            if chains_perfectly {
                score -= 35.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
