        if post_residual == next_item_size {
            score -= 8.0;
        } else if post_residual > next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; mild penalty for big leftovers
            score += 0.02 * (post_residual - next_item_size) as f64;
        }
    } else {
        // Last item: just minimize leftover
        score -= 5.0;
    }

