    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate logic: an empty bin has residual == capacity.
    // Penalize opening a new bin unless current placement would waste a lot
    // or the item fits very poorly everywhere.
    if bin_residual == bin_capacity {
        let open_penalty = 6.0 + 4.0 * (1.0 - progress);
        // If there are few fitting bins and existing bins would leave big waste,
        // opening a new bin becomes attractive: reduce the penalty.
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        score += open_penalty - 0.3 * waste_elsewhere;
