        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            // NEW: refine pair quality — a fresh bin pair that leaves a tiny
            // leftover is nearly perfect; reward it to compete with chain fits.
            if leftover <= 2.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        // NEW: mid-stream escape hatch — if NO open bin can hold the next item
        // after this placement (all would be dead), a fresh bin is cheaper.
        if fitting_bins_count > 0 && progress > 0.35 && progress <= 0.6 {
            let usable_elsewhere = fitting_bins_count > 1;
            if !usable_elsewhere {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps that are "reusable" sizes
    // (multiples of common item granularity) are less harmful.
    let gap = post_residual;
    let gap_class = if gap == 0 {
        0.0
    } else if gap % 10 == 0 {
        0.5
    } else if gap % 5 == 0 {
        1.0
    } else {
        2.0
    };
    score += gap_class * 3.0;

    // Perfect fit bonus
    if gap == 0 {
        score -= 60.0;
    }

    // Lookahead: strongly reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= gap {
            let slack = (gap - next_item_size) as f64;
            score -= 25.0 - 0.2 * slack;
            if gap == next_item_size {
                score -= 40.0;
            }
        } else {
            // next item won't fit here; mildly penalize leaving medium gaps
            if gap >= 10 && gap < 30 {
                score += 8.0;
            }
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, penalized if we can
    // still consolidate into existing bins (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 10.0;
        }
    } else {
        // Prefer bins whose residual is below mean (use up small spaces first)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 15.0 * progress;
    }

    // Integer-division threshold: penalize gaps in dead zone (1..10 unusable-ish)
    if gap >= 1 && gap < 10 {
        score += 6.0;
    }
    // Reward gaps in the sweet zone that many item sizes can use
    if gap >= 30 && gap <= 60 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
