    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // NEW: scarcity pressure — when few fitting bins exist relative to open
    // bins, prefer consolidating into an existing bin rather than diffusing.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - (fitting_bins_count as f64 / open_bins_count.max(1) as f64).min(1.0));
    }

    // New-bin candidate handling: keep fresh bins moderately attractive early,
    // but discourage opening new bins late when open bins can still fit.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        // packing a pair into a fresh bin is acceptable; quantify pair quality:
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            // NEW: a fresh-bin pair is only worth it if the pair is tight;
            // large leftover after a fresh pair is real dead space.
            score += 18.0 * (leftover / cap) * (0.5 + progress);
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        // NEW: mid-stream threshold tightening — new bins should already be
        // discouraged slightly earlier than 0.6 when many bins are open.
        if progress > 0.45 {
            score += 12.0 * (progress - 0.45) / 0.55 * ((open_bins_count as f64) / 20.0).min(1.0);
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = (item_size as f64) / (bin_residual.max(1) as f64);
    if fill_ratio > 0.85 {
        score -= 18.0 * fill_ratio;
    } else if fill_ratio > 0.6 {
        score -= 8.0 * fill_ratio;
    }

    // Penalize leaving awkward dead space (small residuals that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin: strong bonus to use the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward it; if the next item would be blocked, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 4.0;
        }
        // Perfect chain: item + next item exactly fill the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: empty bins get a moderate default score so that
    // they are only chosen when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        if progress > 0.7 {
            score -= 8.0 * progress;
        }
        // If many bins are open and none fit well, prefer consolidation.
        if open_bins_count > 10 {
            score += 5.0;
        }
    }

    // Global fragmentation pressure: if mean residual across open bins is low,
    // we are running tight — prefer placements that preserve flexibility.
    if mean_residual < 15.0 {
        score += 6.0;
    } else if mean_residual > 50.0 {
        score -= 4.0;
    }

    // Slight preference for consolidating into already-open bins vs. spreading.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, mildly super-linear to punish large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of residual with stream progress:
    // early on tolerate slack; late in the stream demand tight packing.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits smoothly (smooth bump around small post_residual).
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Exact chain match: post residual exactly equals next item -> very strong bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            // pair leaves almost nothing behind: extra reward
            if post_residual - next_item_size <= 2 {
                score -= 25.0;
            } else if post_residual - next_item_size <= 6 {
                // near-chain match: mild extra reward to reduce dead space
                score -= 8.0 * (1.0 - (post_residual - next_item_size - 2) as f64 / 4.0);
            }
        } else {
            // Dead space that next item cannot use: smooth penalty, sharpened
            // when the gap is large relative to the residual (true dead space).
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Coupling with mean residual: placing into a bin whose residual is below
    // mean is good (compact bins); above mean is penalized smoothly.
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Two-step lookahead: if the next item cannot fit here, estimate whether the
    // one after (approximated by next_item_size again) would pair with the
    // current item in this bin — discourage dumping unusable slack.
    if next_item_size > 0 && post_residual < next_item_size {
        let pair_slack = (bin_capacity - item_size - next_item_size) as f64;
        if item_size + next_item_size <= bin_capacity {
            // The item would pair perfectly elsewhere; leaving it here wastes a
            // full pairing slot. Penalize proportionally to usable slack lost.
            score += 14.0 * (1.0 - pair_slack / cap) * (0.4 + 0.6 * progress);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep fresh bins moderately attractive early,
    // but discourage opening new bins late when open bins can still fit.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        // packing a pair into a fresh bin is acceptable; quantify pair quality:
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        // Late-stream exception: if only one open bin fits and its post-fit
        // residual is large dead space, a fresh bin with a clean pair is better.
        if progress > 0.75 && fitting_bins_count == 1 && next_item_size > 0
            && post_residual >= next_item_size
            && post_residual - next_item_size > bin_capacity / 8
