        score += 15.0 * (if x < nxt && x > 0.0 { (nxt - x) } else { 0.0 });
    }

    // Last-chance bin: smooth sigmoid-like reward to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - x * x);
    }

    // Mild penalty on many open bins, scaled by progress.
    score += 0.5 * open_bins_count as f64 * t;

    // New-bin candidate: keep neutral baseline, slightly discouraged unless x ~ 1.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * t;
    }

    score
}

