pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, mildly super-linear to punish large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of residual with stream progress:
    // early on tolerate slack; late in the stream demand tight packing.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits smoothly (smooth bump around small post_residual).
