    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Progress-pressure coupling: demand tight packing late in the stream
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Smooth near-perfect-fit bump
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            if post_residual - next_item_size <= 2 {
                score -= 25.0;
            } else if post_residual - next_item_size <= 6 {
                score -= 8.0 * (1.0 - (post_residual - next_item_size - 2) as f64 / 4.0);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Mean-residual compaction coupling
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
        }
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: let relative tightness dominate
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * (50.0 + 120.0 * p2) * (1.0 - progress);
    score -= norm_pr * (30.0 + 60.0 * p3);

    // Penalize small residuals more as stream advances (dead space matters late)
    let small_res = (pr / cap).powi(3);
    score += small_res * (40.0 + 200.0 * p2 + 150.0 * p3);

    // Lookahead: reward bins whose post residual fits next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let fit_quality = (next_item_size as f64 / pr).powi(2);
        score -= 25.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 45.0 + 30.0 * progress;
    }

    // Mean residual coupling: prefer bins close to mean residual (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + progress);

    // New-bin candidate: opening a bin is penalized mildly early, more late
    if bin_residual == bin_capacity {
        score += 60.0 + 80.0 * progress + 40.0 * p2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
