pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions /10
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 10.0).floor(); // 0..9 harmonic class

    // Reward residuals that fall into "usable" harmonic classes for typical items.
    // Small residuals (< ~10) are dead space -> penalize extra.
    if post_residual < 10 {
        score += 25.0;
    } else {
        // Reward exact harmonic sweet spots: residual divisible by common item sizes
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                bonus += 6.0;
            }
        }
        score -= bonus;

        // Modulo-class coupling: post_residual mod 10 near 0 is clean
        let m = post_residual % 10;
        score -= (10 - m as i32 as f64).abs().min(m as f64) as f64 * 0.8;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward proportionally to how well next item fills leftover
        let fill = next_item_size as f64 / pr.max(1.0);
        score -= fill * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Prefer new bin when current fit leaves large dead space
        // and few bins fit the item (fragmentation risk)
        let dead = pr;
        if dead > cap * 0.4 && fitting_bins_count <= 2 {
            score -= 20.0;
        } else {
            score += 15.0; // penalize opening new bins when a decent fit exists
        }
        // Late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer tighter bins overall (low residual before placement)
    score -= (bin_residual as f64 / cap) * 5.0;

    // Many open bins: encourage consolidation via mean residual coupling
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;

    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Reward tight fits smoothly, stronger late in the stream
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Dead space classification (parent's thresholds, sharpened)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0 * (0.5 + progress);
    } else if post_residual <= 20 {
        score += 10.0;
    } else {
        score -= 8.0;
    }

    // Lookahead chain logic with exact-match dominance
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let pair_res = post_residual - next_item_size;
            if pair_res == 0 {
                score -= 45.0;
            } else if pair_res < 10 {
                score -= 20.0;
            } else {
                let fill = next_item_size as f64 / pr.max(1.0);
                score -= 20.0 * fill * (1.0 - norm_pr);
            }
        } else {
            // next item can't use this residual: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 5.0 + gap * 0.35 + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Mismatched classes: huge item into mostly-empty bin wastes it
    let item_class = item_size / (bin_capacity / 4);
    if item_class >= 3 && post_residual > 30 {
        score += 12.0;
    }

    // Mean residual coupling: below-mean residual fits are compact
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: prefer existing bins unless fragmentation is bad
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / cap;
        if item_size > 50 && avg_fragmentation < 0.35 {
            score -= 55.0;
        } else {
            let open_pressure = (open_bins_count as f64).ln().max(0.0);
            score += 25.0 + open_pressure * (10.0 + 30.0 * progress);
        }
        if next_item_size > 0 && next_item_size > 60 {
            score -= 15.0;
        }
        // Pairing into a fresh bin early is acceptable
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress) - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
        // Late-stream: opening new bins is expensive
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
    }

    // Late-stream consolidation scale
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
