            if post_residual - next_item_size <= 2 {
                score -= 25.0;
            } else if post_residual - next_item_size <= 6 {
                // near-chain match: mild extra reward to reduce dead space
                score -= 8.0 * (1.0 - (post_residual - next_item_size - 2) as f64 / 4.0);
            }
        } else {
            // Dead space that next item cannot use: smooth penalty, sharpened
            // when the gap is large relative to the residual (true dead space).
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // NEW: two-step lookahead — if placing here leaves a residual that the next
    // item cannot use, but a slightly larger residual would trap even more, prefer
    // bins whose leftover stays "usable" by small future items. Penalize residuals
    // falling into common dead zones (just below typical small-item sizes).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
