    // when only a few fit, accept more readily to avoid fragmentation.
    if fitting_bins_count > 1 {
        let pickiness = ((fitting_bins_count as f64 - 1.0).ln() + 1.0).min(3.0);
        score += 4.0 * pickiness * norm_pr * (0.5 + progress);
