        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        // NEW: if the best alternative fit would strand a large dead residual
        // (post_residual tiny relative to next item), a fresh bin becomes viable.
        if next_item_size > 0 && fitting_bins_count > 0 && post_residual < next_item_size {
            let stranded = (next_item_size - post_residual) as f64 / cap;
            score -= 35.0 * stranded * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

