}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: small dead space is fine,
    // mid-range residuals are the dangerous "dead zone".
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Classify residual into harmonic bands via integer division thresholds
    let band = post_residual / 10; // 0..=10
    let band_penalty: f64 = match band {
        0 => 0.0,                      // near-perfect
        1 => 2.0,                      // 10-19: still usable for tiny items
        2 | 3 => 8.0,                  // 20-39: awkward mid zone
        4 | 5 => 15.0,                 // 40-59: worst dead zone
        6 | 7 => 10.0,                 // 60-79: fits medium items
        _ => 4.0,                      // 80+: fresh-bin-like, fine
    };
    score += band_penalty;

    // Lookahead synergy: if the next item fits the post-residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            score -= 30.0 + 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize residual proportionally more
            score += 5.0 + 10.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 250.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (already via post_residual)
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // Only prefer it when no open bin gives a decent fit, i.e. when this call
    // is the empty-bin call and the item leaves a large, awkward residual elsewhere.
    if bin_residual == bin_capacity {
        // base preference for opening a new bin when bins are scarce / residuals are bad
        let avg_bad = (mean_residual - item_size as f64).max(0.0);
        // discourage default opening
        score += 60.0;
        // but if the item is large relative to mean residual, opening is attractive
        score -= 40.0 * (item_size as f64 / cap);
        // late in the stream, avoid opening bins for small leftovers
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 25 && progress > 0.7 {
            score += 40.0;
        }
        // if mean residual is large, better to use open bins
        score += 0.3 * avg_bad;
        // empty-bin perfect structural bonus: item exactly half or third of capacity
        if bin_capacity % item_size == 0 {
            score -= 20.0;
        }
        let _ = open_bins_count;
    }

    // Mild global pressure: prefer reusing bins when many are open
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Small tie-breaker toward balanced residual usage vs mean
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, mildly super-linear to punish large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of residual with stream progress:
    // early on tolerate slack; late in the stream demand tight packing.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits smoothly (smooth bump around small post_residual).
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Exact chain match: post residual exactly equals next item -> very strong bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            // pair leaves almost nothing behind: extra reward
            if post_residual - next_item_size <= 2 {
                score -= 25.0;
            } else if post_residual - next_item_size <= 6 {
                // near-chain match: mild extra reward to reduce dead space
                score -= 8.0 * (1.0 - (post_residual - next_item_size - 2) as f64 / 4.0);
            }
            // NEW: two-step lookahead — reward residuals that can host the next
            // item and still leave a remainder usable by typical follow-ups.
            let rem = post_residual - next_item_size;
            if rem > 6 && rem as f64 >= next_item_size as f64 * 0.35 {
                score -= 5.0 * (rem as f64 / pr.max(1.0));
            }
        } else {
            // Dead space that next item cannot use: smooth penalty, sharpened
            // when the gap is large relative to the residual (true dead space).
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Coupling with mean residual: placing into a bin whose residual is below
    // mean is good (compact bins); above mean is penalized smoothly.
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Dead-space-aware mean coupling: bins whose residual is far above the
    // mean AND unusable by the next item accumulate compounding dead space.
    if next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (norm_pr - mean_norm).max(0.0) * gap / next_item_size.max(1) as f64;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep fresh bins moderately attractive early,
    // but discourage opening new bins late when open bins can still fit.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        // packing a pair into a fresh bin is acceptable; quantify pair quality:
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            // A fresh-bin pair leaving a tiny leftover is nearly perfect; reward
            // it to compete with chain fits in open bins.
            if leftover <= 2.0 {
                score -= 30.0 * (1.0 - progress);
            } else if leftover <= 6.0 {
                score -= 12.0 * (1.0 - (leftover - 2.0) / 4.0) * (1.0 - progress);
            }
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        // Mid-stream escape hatch — if NO open bin can hold the next item
        // after this placement (all would be dead), a fresh bin is cheaper.
        if fitting_bins_count > 0 && progress > 0.35 && progress <= 0.6 {
            if fitting_bins_count == 1 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

