                // near-chain match: mild extra reward to reduce dead space
                score -= 8.0 * (1.0 - (post_residual - next_item_size - 2) as f64 / 4.0);
            }
            // NEW: fractional fill of the residual by the next item — reward
            // high utilization of the leftover space (fine-grained fitting).
            score -= 14.0 * fill * fill;
        } else {
            // Dead space that next item cannot use: smooth penalty, sharpened
            // when the gap is large relative to the residual (true dead space).
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
            // NEW: compounding dead-space penalty — unusable residual blocks
            // future packing; punish proportionally to stream progress.
            score += 10.0 * dead_frac * norm_pr * (0.5 + progress);
        }
    }

    // Coupling with mean residual: placing into a bin whose residual is below
    // mean is good (compact bins); above mean is penalized smoothly.
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // NEW: dead-space-aware mean coupling. Bins whose residual is far above the
    // mean AND unusable by the next item accumulate compounding dead space.
    if next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (norm_pr - mean_norm).max(0.0) * gap / next_item_size.max(1) as f64;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep fresh bins moderately attractive early,
    // but discourage opening new bins late when open bins can still fit.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        // packing a pair into a fresh bin is acceptable; quantify pair quality:
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            // NEW: refine pair quality — a fresh bin pair that leaves a tiny
            // leftover is nearly perfect; reward it to compete with chain fits.
            if leftover <= 2.0 {
                score -= 30.0 * (1.0 - progress);
            } else if leftover <= 6.0 {
                score -= 12.0 * (1.0 - (leftover - 2.0) / 4.0) * (1.0 - progress);
            }
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        // NEW: mid-stream escape hatch — if NO open bin can hold the next item
        // after this placement (all would be dead), a fresh bin is cheaper.
        if fitting_bins_count > 0 && progress > 0.35 && progress <= 0.6 {
            let usable_elsewhere = fitting_bins_count > 1;
            if !usable_elsewhere {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Penalize small unusable dead space that no item (min size 1..10 typical) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Lookahead: penalize if leftover residual is awkwardly close to but smaller
    // than the next item (dead space for the known future), reward if next item fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size - post_residual <= 10 {
            score += 10.0; // near-miss: residual almost fits next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin gets a baseline penalty so we
    // only open it when existing fits are poor; the penalty shrinks as the stream
    // progresses and as the fleet of open bins grows (fragmentation pressure).
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        let poor_fit = (100.0 - fit_ratio * 100.0).clamp(0.0, 100.0);
        score += 20.0 + 15.0 * (1.0 - t) - 6.0 * open_pressure - 0.10 * poor_fit;
    } else {
        // Mild preference for bins with below-average residual (consolidate waste).
        score += 0.05 * (bin_residual as f64 - mean_residual).max(-40.0).min(40.0);
    }

    // Slight early-stream bias toward filling existing bins aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    score
}

