            let usable_elsewhere = fitting_bins_count > 1;
            if !usable_elsewhere {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are "unusable" (small) are heavily penalized.
    // Treat post_residual < 10 (below smallest plausible item) as pure dead space;
    // small-but-usable gaps are also penalized super-linearly.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: big penalty on top of its small value.
        score += 25.0;
    } else {
        // Usable gap: penalize quadratically to prefer tight fits.
        let pr = post_residual as f64;
        score += (pr * pr) / 50.0;
    }

    // If the lookahead item fits exactly in the post-residual, this placement is
    // chain-friendly: reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item can't fit the leftover, leftover likely becomes dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one
    // (penalize the new-bin candidate and mildly favor existing bins).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = 100.0 + (open_bins_count as f64) * 4.0;
        // Late in the stream, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If a decently tight fit exists elsewhere (low mean residual), opening is worse.
        if mean_residual > 0.0 && (bin_residual as f64 - item_size as f64) > mean_residual {
            score += 10.0;
        }
        // Last-chance override: never open a new bin when it's the only fitting bin.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
