    // this placement chains nicely; reward it proportionally.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / cap;
        score -= 45.0 * chain * (1.0 - post / cap);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here afterwards; slight penalty scaled by gap.
        let gap = (next_item_size as f64 - post).min(cap);
        score += 12.0 * gap / cap;
