    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer the bin among many that leaves least residual.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
