    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, mildly super-linear to punish large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of residual with stream progress.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits smoothly.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chain logic, sharpened with a graded exact-match bonus that
    // scales with how "scarce" fitting bins are.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            let scarcity = if fitting_bins_count > 1 { 1.0 } else { 1.35 };
            score -= 900.0 * scarcity;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let leftover_after = post_residual - next_item_size;
            if leftover_after <= 2 {
                score -= 25.0;
            } else if leftover_after <= 6 {
                score -= 8.0 * (1.0 - (leftover_after - 2) as f64 / 4.0);
            } else {
                // NEW: graded decay for larger leftovers instead of nothing —
                // smaller leftovers still mildly preferred (compaction pressure).
                let lf = leftover_after as f64;
                score -= 6.0 * (1.0 - (lf - 6.0).min(cap * 0.5) / (cap * 0.5)) * (1.0 - norm_pr);
            }
            // NEW: two-step anticipation — if the leftover after the pair still
            // accommodates the next item again, reward the chain continuation.
            if leftover_after as f64 >= next_item_size as f64 && leftover_after > 0 {
                score -= 12.0 * (1.0 - progress) * (next_item_size as f64 / cap);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Coupling with mean residual: below-mean residual bins are compact.
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Dead-space-aware mean coupling.
    if next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (norm_pr - mean_norm).max(0.0) * gap / next_item_size.max(1) as f64;
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            if leftover <= 2.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress <= 0.6 && fitting_bins_count == 1 {
            score -= 18.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    let mut score = pr;

    // Non-linear coupling: reward high fill with a saturating polynomial term
    score -= 25.0 * fill * fill * (1.0 + 0.5 * progress);

    // Penalize dead space quadratically when residual can't fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let next_ratio = next_item_size as f64 / cap;
        score += 18.0 * next_ratio * (1.0 - fill) * (1.0 - fill);
    } else if next_item_size > 0 {
        // Reward leaving space exactly usable by the lookahead item
        let tightness = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 12.0 * tightness * tightness;
    }

    // Last-chance bonus: smooth exponential in fitting scarcity
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize mildly, less so when existing bins are full-ish
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        score += 20.0 - 15.0 * mean_fill * mean_fill - 8.0 * progress;
    }

    // Mild penalty for bins that deviate from mean residual (prefer homogeneity)
    score += 0.05 * (pr - mean_residual).abs();

    // Small smooth tie-breaker
    score -= 3.0 * fit_ratio * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, mildly super-linear to punish large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of residual with stream progress:
    // early on tolerate slack; late in the stream demand tight packing.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits smoothly (smooth bump around small post_residual).
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Exact chain match: post residual exactly equals next item -> very strong bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            // pair leaves almost nothing behind: extra reward
            if post_residual - next_item_size <= 2 {
                score -= 25.0;
            } else if post_residual - next_item_size <= 6 {
                score -= 8.0 * (1.0 - (post_residual - next_item_size - 2) as f64 / 4.0);
            }
        } else {
            // Dead space that next item cannot use: smooth penalty, sharpened
            // when the gap is large relative to the residual (true dead space).
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
            // Two-step lookahead: if the dead space left here matches what a
            // later residual could absorb, soften the penalty slightly.
            if gap as u32 + item_size <= bin_capacity {
                score -= 3.0 * (1.0 - norm_pr);
            }
        }
    }

    // Coupling with mean residual: placing into a bin whose residual is below
    // mean is good (compact bins); above mean is penalized smoothly.
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep fresh bins moderately attractive early,
    // but discourage opening new bins late when open bins can still fit.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        // packing a pair into a fresh bin is acceptable; quantify pair quality:
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            // triple fit lookahead: fresh bin that can host item + next + more
            if next_item_size > 0 {
                let after_pair = bin_capacity - item_size - next_item_size;
                if after_pair > 0 && next_item_size as u32 <= after_pair {
                    score -= 15.0;
                }
            }
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Late-stream consolidation: scale scores down so relative tightness dominates.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of wasted space

    // Class boundaries via integer division thresholds (harmonic classes of C/2, C/4, C/8).
    let class = if post_residual == 0 {
        0u32 // perfect fit — best possible outcome
    } else if post_residual <= bin_capacity / 8 {
        1
    } else if post_residual <= bin_capacity / 4 {
        2
    } else if post_residual <= bin_capacity / 2 {
        3
    } else {
        4
    };

    // Reward tight fits strongly per class (larger class = worse, larger penalty).
    score += class as f64 * 3.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next_item_size fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic compatibility: reward when post_residual class matches next item's
            // residue class (mod 10 buckets), i.e. leftover is reusable by the next item.
            let compat = (post_residual % 10).min(next_item_size % 10);
            score -= 8.0 + (compat as f64) * 0.3;
            // Extra reward if next item fills leftover almost exactly.
            let gap = post_residual - next_item_size;
            if gap <= bin_capacity / 8 {
                score -= 6.0;
            }
        } else {
            // Leftover too small for next item: penalize proportionally to how close it is
            // to being useful (near-miss dead space is the worst kind).
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 + miss * 0.15;
        }
    } else {
        // Last item: only final waste matters; squeeze everything.
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it unattractive
    // unless all alternatives would create bad classes (score already high there).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; modulated by stream progress and open bin count.
        score += 25.0 + 10.0 * (step_index as f64 / (total_items.max(1) as f64));
        // If the item is large relative to capacity, opening fresh is less bad.
        score -= (item_size as f64 / cap) * 15.0;
        // If many bins are open and mean residual is small, opening a bin is more acceptable.
        if (mean_residual < 15.0) && open_bins_count > 2 {
            score -= 18.0;
        }
    } else {
        // Mild preference for reusing bins as the stream progresses (consolidation).
        score -= 1.5 + 2.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Penalize bins whose residual deviates far from the mean (keep residuals homogeneous
    // so future harmonic classes stay predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Modulo-based tie-break: prefer residuals that are multiples of 10 (aligned classes),
    // which are more likely to match future integer item sizes exactly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
