    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // NEW: two-step lookahead. If placing here still leaves room for the next
    // item AND the item after could also use the remainder, this bin is a
    // chaining hub — reward it proportionally to how much of the residual
    // gets consumed across the two-step horizon.
    if next_item_size > 0 && next_item_size <= post_residual {
        let rem = post_residual - next_item_size;
        // Reward consuming residual fully; the smaller the remainder, the better.
        let rem_norm = rem as f64 / cap;
        score -= 14.0 * (1.0 - rem_norm) * (0.4 + 0.6 * progress);
        // If the remainder is unusable dead space (too small for typical items),
        // penalize leaving fragments between 1 and 4 only when progress is high.
        if rem > 0 && rem <= 4 && progress > 0.5 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // NEW: competition-aware bonus. When several bins fit the item, prefer the
    // one whose post-residual is closest to the next item size (best-match
    // chaining), scaled by how many alternatives exist.
    if next_item_size > 0 && fitting_bins_count > 1 && bin_residual != bin_capacity {
        let dist = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            ((next_item_size - post_residual) * 2) as f64
        };
        score += 3.0 * (dist as f64).ln().max(0.0) * (fitting_bins_count as f64).ln().max(1.0);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
