    let next_class = if next_item_size == 0 { 0 } else { next_item_size / (bin_capacity / 4).max(1) };

    // Non-linear progress pressure: early tolerate slack, late demand tightness.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

