}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, mildly super-linear to punish large residuals.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of residual with stream progress:
    // early on tolerate slack; late in the stream demand tight packing.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Reward near-perfect fits smoothly (smooth bump around small post_residual).
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Exact chain match: post residual exactly equals next item -> very strong bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            // pair leaves almost nothing behind: extra reward
            let leftover_after = post_residual - next_item_size;
            if leftover_after <= 2 {
                score -= 25.0;
            } else if leftover_after <= 6 {
                score -= 8.0 * (1.0 - (leftover_after - 2) as f64 / 4.0);
            }
            // NEW: if leftover after the chain can serve the item after next,
            // this bin becomes a multi-step chain anchor; reward moderately.
            if leftover_after > 0 && leftover_after <= 12 && progress > 0.3 {
                score -= 6.0 * (1.0 - leftover_after as f64 / 12.0) * progress;
            }
        } else {
            // Dead space that next item cannot use: smooth penalty, sharpened
            // when the gap is large relative to the residual (true dead space).
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
            // NEW: dead space is worse when many bins compete — a bin that
            // wastes space while alternatives exist should be deprioritized.
            if fitting_bins_count >= 2 {
                score += 6.0 * dead_frac * (open_bins_count as f64).ln().max(0.0);
            }
        }
    }

    // Coupling with mean residual: placing into a bin whose residual is below
    // mean is good (compact bins); above mean is penalized smoothly.
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep fresh bins moderately attractive early,
    // but discourage opening new bins late when open bins can still fit.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        // packing a pair into a fresh bin is acceptable; quantify pair quality:
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            // NEW: a fresh bin is genuinely worth opening if the pair leaves a
            // residual that can absorb future small items (tight triple start).
            if leftover <= 8 {
                score -= 12.0;
            }
        }
        // NEW: opening a new bin while the current bin still has usable space
        // for the NEXT item wastes the chain; penalize that scenario.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size.min(bin_residual) {
            score += 18.0 * (0.5 + progress);
        }
        // Late-stream: opening a new bin is expensive; make it clearly worse
        // unless every open bin would leave unusable dead space.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        if fitting_bins_count == 0 {
            score = -10.0;
