        // typical (mean-sized) item, making the fresh bin highly productive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let mean_item = (mean_residual + (cap - mean_residual) * 0.5).max(1.0);
            if chain_left >= 1.0 && chain_left <= 0.35 * cap {
                score -= 22.0 * (1.0 - chain_left / (0.35 * cap)) * (1.0 - 0.6 * progress);
            }
            if chain_left >= mean_item * 0.9 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        // Late stream with many open bins — consolidation pressure.
        if progress > 0.7 && open_bins_count > 6 {
            score += 10.0 * (open_bins_count as f64).ln() * (progress - 0.7) / 0.3;
        }
        // Mid-stream, avoid opening fresh bins when any open bin fits the
        // item with small dead space relative to the item itself.
        if fitting_bins_count > 0 && progress > 0.3 && item_size as f64 >= 0.25 * cap {
            score += 14.0 * (progress - 0.3) / 0.7;
        }
        // MUTATION: fresh-bin avoidance when the best open bin would end within a
        // tiny dead margin — reuse is strictly better than a fresh split.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_dead = bin_residual.saturating_sub(item_size);
            if best_dead > 0 && (best_dead as f64) <= 0.06 * cap {
                score += 20.0 * (1.0 - best_dead as f64 / (0.06 * cap)) * (0.4 + progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    if !is_new_bin && post_residual == 0 {
        score -= 60.0;
    }

    if !is_new_bin && post_residual > 0 && post_residual <= 3 {
        score -= 35.0 * (1.0 - post_residual as f64 / 4.0);
        // Extra progress-scaled nudge for late perfect fits.
        score -= 20.0 * progress * (1.0 - post_residual as f64 / 4.0);
    }

    // Two-step lookahead in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) >= 0.5 * (next_item_size as f64) && (after as f64) <= 0.9 * cap {
            score -= 10.0 * (1.0 - after as f64 / cap) * (0.5 + progress);
        }
    }

    // Divisibility-aware residual shaping.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 6.0 * (1.0 - norm_pr) * (0.5 + progress);
        } else if next_item_size - rem <= 2 {
            score += 5.0 * progress;
        }
    }

    // Variance-targeting squeeze.
    if !is_new_bin {
        let dev = (norm_pr - mean_norm).abs();
        if dev > 0.18 {
            score += 18.0 * (dev - 0.18) * progress;
        }
    }

    // Dead-space ratio guard — residual that can never host a mean-sized
    // item is effectively wasted; penalize proportionally to progress.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = 1.0 - pr / (next_item_size as f64);
        score += 10.0 * dead_frac * dead_frac * (0.4 + progress);
    }

    // MUTATION: residual-productivity shaping — reward open bins whose leftover
    // after this item still exceeds the mean item size, penalize ones that strand
    // a sliver below the mean, scaled by how many alternatives exist.
    if !is_new_bin && post_residual > 0 {
        let mean_item = mean_residual.max(1.0);
        if pr >= mean_item {
            score -= 7.0 * (pr / cap) * (0.5 + progress);
        } else {
            let strand = 1.0 - pr / mean_item;
            let alt = ((fitting_bins_count.max(1) - 1) as f64).ln().max(0.0);
            score += 9.0 * strand * strand * (0.3 + 0.7 * progress) * (1.0 + 0.3 * alt);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;
    let mean_norm = mean_residual / cap;

    // Base: wasted space, super-linear punishment of large residuals.
    let mut score = pr + 14.0 * norm_pr * norm_pr * cap;

    // Progress-coupled residual pressure.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Smooth reward for near-perfect fits.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chaining with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let leftover_after = post_residual - next_item_size;
            if leftover_after <= 2 {
                score -= 25.0;
            } else if leftover_after <= 6 {
                score -= 8.0 * (1.0 - (leftover_after - 2) as f64 / 4.0);
            }
            if leftover_after > 0 && (leftover_after as f64) < 0.5 * (next_item_size as f64) {
                score += 4.0 * (1.0 - leftover_after as f64 / (next_item_size as f64));
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / next_item_size.max(1) as f64;
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Mean-residual coupling: below-mean bins are compact.
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Compounding dead-space coupling.
    if next_item_size > 0 && post_residual < next_item_size && !is_new_bin {
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (norm_pr - mean_norm).max(0.0) * gap / next_item_size.max(1) as f64;
    }

    // Dead-space ratio penalty.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = pr / cap;
        if dead_ratio > 0.20 {
            score += 34.0 * (dead_ratio - 0.20) * (0.5 + progress) * (1.0 + mean_norm);
        }
    }

    // Multi-fit competition.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 {
        let mismatch = (pr - next_item_size as f64).abs() / cap;
        let comp = ((fitting_bins_count - 1) as f64).ln().max(0.0);
        score += 6.0 * mismatch * comp;
        if pr == next_item_size as f64 {
            score -= 5.0 * comp;
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            if leftover <= 2.0 {
