        let after = post_residual - next_item_size;
        let half_next = next_item_size as f64 * 0.5;
        if after > 0 && (after as f64) < half_next {
            score += 7.0 * (1.0 - after as f64 / half_next) * (0.3 + progress);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

