            let two = item_size + next_item_size;
            if two < bin_capacity {
                let third_left = bin_capacity - two;
                if (third_left as f64) >= mean_residual * 0.5 {
                    score -= 14.0 * (1.0 - progress) * (1.0 - third_left as f64 / cap);
                }
            }
        }
        // MUTATION: fresh-bin waste ceiling — reject fresh bins whose post-fill
        // leftover (after item + next) exceeds the mean item size; such leftover
        // is unlikely to be refilled and becomes permanent dead space.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            if leftover > mean_residual.max(1.0) * 1.2 {
                score += 20.0 * (1.0 - progress) * (leftover / cap);
            }
        }
