            score += 12.0 * (0.2 - mean_norm) * (0.5 + progress);
        }
        // Residual-variance-aware fresh-bin guard — when residual spread is low
        // (uniform stream), open bins fit predictably; discourage fresh bins.
        if fitting_bins_count > 0 && progress > 0.25 {
            let spread = (mean_norm - 0.5).abs();
            if spread < 0.25 {
                score += 16.0 * (0.25 - spread) * progress;
            }
        }
        // Triple-chain lookahead — if item+next+mean-sized follow-up still fits
        // in a fresh bin, opening is very attractive early/mid stream.
        if next_item_size > 0 && progress < 0.55 {
            let two = item_size + next_item_size;
            if two < bin_capacity {
                let third_left = bin_capacity - two;
                if (third_left as f64) >= mean_residual * 0.5 {
                    score -= 14.0 * (1.0 - progress) * (1.0 - third_left as f64 / cap);
                }
            }
        }
        // MUTATION: fresh-bin dead-space floor — if the leftover after item+next
        // would be smaller than the running mean item size, that dead space is
        // likely permanent; penalize opening a fresh bin with such a leftover.
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            if leftover < mean_residual * 0.6 {
                score += 20.0 * (1.0 - leftover / (mean_residual * 0.6).max(1.0)) * (0.4 + progress);
            }
        }
        // MUTATION: open-bin dead-space rescue — if placing into an open bin
        // would leave a residual that still hosts the next item, reward it
        // proportionally to how tight the post-fit residual is relative to
        // the mean residual (compaction toward zero waste).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            let target = mean_residual.max(1.0);
            if (after as f64) >= target * 0.5 {
                score -= 8.0 * (1.0 - (after as f64 / target).min(1.0)) * (0.5 + progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    if !is_new_bin && post_residual == 0 {
        score -= 60.0;
    }

    if !is_new_bin && post_residual > 0 && post_residual <= 3 {
        score -= 35.0 * (1.0 - post_residual as f64 / 4.0);
        score -= 20.0 * progress * (1.0 - post_residual as f64 / 4.0);
    }

    // Two-step lookahead in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) >= 0.5 * (next_item_size as f64) && (after as f64) <= 0.9 * cap {
            score -= 10.0 * (1.0 - after as f64 / cap) * (0.5 + progress);
        }
    }

    // Divisibility-aware residual shaping.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 6.0 * (1.0 - norm_pr) * (0.5 + progress);
        } else if next_item_size - rem <= 2 {
            score += 5.0 * progress;
        }
    }

    // Variance-targeting squeeze.
    if !is_new_bin {
        let dev = (norm_pr - mean_norm).abs();
        if dev > 0.18 {
            score += 18.0 * (dev - 0.18) * progress;
        }
    }

    // Dead-space ratio guard: residual that can never host a mean-sized item.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = 1.0 - pr / (next_item_size as f64);
        score += 10.0 * dead_frac * dead_frac * (0.4 + progress);
    }

    // Dead-space productivity check — residual below the running mean item size
    // late in the stream is likely permanent waste; penalize harder.
    if !is_new_bin && post_residual > 0 && progress > 0.5 {
        let mean_item_est = mean_residual.max(1.0);
        if (pr as f64) < mean_item_est * 0.6 {
            score += 16.0 * (1.0 - pr / (mean_item_est * 0.6)) * (progress - 0.5);
        }
    }

    // Exact-fill chain reward — residual that exactly accommodates the
    // next item AND then a small remainder item is prime compaction territory.
    if !is_new_bin && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) <= mean_residual * 0.35 && after > 0 {
            score -= 12.0 * (1.0 - after as f64 / (mean_residual * 0.35).max(1.0)) * (0.5 + progress);
        }
    }

    // MUTATION: endgame squeeze — in the final stretch, small residuals in open
    // bins become nearly useless; tighten preference for bins that can still
    // absorb the next item exactly or near-exactly.
    if !is_new_bin && progress > 0.8 && next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 0.1 * cap {
                score -= 10.0 * (1.0 - slack / (0.1 * cap)) * (progress - 0.8) / 0.2;
            }
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
