        }
        // Triple-chain lookahead — fresh bin attractive early/mid stream when
        // residual after item+next can still host a mean-sized item.
        if next_item_size > 0 && progress < 0.55 {
            let two = item_size + next_item_size;
            if two < bin_capacity {
                let third_left = bin_capacity - two;
                if (third_left as f64) >= mean_residual * 0.5 {
                    score -= 14.0 * (1.0 - progress) * (1.0 - third_left as f64 / cap);
                }
            }
        }
        // MUTATION: fresh-bin dead-space forecast — a fresh bin is only worth
        // opening if the post-pairing leftover is small OR large enough to be
        // reusable; mid-sized stranded leftovers forecast permanent waste.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let stranded_lo = 0.12 * cap;
            let stranded_hi = 0.45 * cap;
            if chain_left > stranded_lo && chain_left < stranded_hi {
                // Distance from the "safe" edges of the stranded zone.
                let edge = (chain_left - stranded_lo).min(stranded_hi - chain_left)
                    / (stranded_hi - stranded_lo);
                score += 26.0 * (1.0 - edge) * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION: item-size class awareness — big items (>0.4 cap) into fresh
        // bins are risky late; they leave awkward residuals that rarely refill.
        if (item_size as f64) > 0.4 * cap && progress > 0.45 && fitting_bins_count > 0 {
            score += 20.0 * (progress - 0.45) / 0.55
                * ((item_size as f64) / cap - 0.4) / 0.6;
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    if !is_new_bin && post_residual == 0 {
        score -= 60.0;
    }

    if !is_new_bin && post_residual > 0 && post_residual <= 3 {
        score -= 35.0 * (1.0 - post_residual as f64 / 4.0);
        score -= 20.0 * progress * (1.0 - post_residual as f64 / 4.0);
    }

    // Two-step lookahead in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) >= 0.5 * (next_item_size as f64) && (after as f64) <= 0.9 * cap {
            score -= 10.0 * (1.0 - after as f64 / cap) * (0.5 + progress);
