                score -= 10.0 * (1.0 - 0.4 * progress);
            }
        }
        // Fresh-bin sizing vs. next item.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt > 0.5 * cap {
                score -= 10.0 * (1.0 - progress);
            } else if nxt < 0.15 * cap {
