        }
    }

    // Exact-fill chain reward — residual that exactly accommodates the
    // next item AND then a small remainder item is prime compaction territory.
    if !is_new_bin && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) <= mean_residual * 0.35 && after > 0 {
            score -= 12.0 * (1.0 - after as f64 / (mean_residual * 0.35).max(1.0)) * (0.5 + progress);
        }
    }

    // MUTATION: post-fill usability reward — after placing the item, if the
    // remaining residual can still host the next item with room to spare for a
    // mean-sized follow-up, this bin is a strong compaction hub.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
