    if !is_new_bin && norm_pr < 0.08 {
        score -= 18.0 * (0.08 - norm_pr) / 0.08 * (0.4 + 0.6 * progress);
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

