        if (after as f64) >= 0.5 * (next_item_size as f64) && (after as f64) <= 0.9 * cap {
            score -= 10.0 * (1.0 - after as f64 / cap) * (0.5 + progress);
        }
    }

    // Divisibility-aware residual shaping.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 6.0 * (1.0 - norm_pr) * (0.5 + progress);
        } else if next_item_size - rem <= 2 {
            score += 5.0 * progress;
        }
    }

    // Variance-targeting squeeze.
    if !is_new_bin {
        let dev = (norm_pr - mean_norm).abs();
        if dev > 0.18 {
            score += 18.0 * (dev - 0.18) * progress;
        }
    }

    // Dead-space ratio guard: residual that can never host a mean-sized item.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = 1.0 - pr / (next_item_size as f64);
        score += 10.0 * dead_frac * dead_frac * (0.4 + progress);
    }

    // Dead-space productivity check.
    if !is_new_bin && post_residual > 0 && progress > 0.5 {
        let mean_item_est = mean_residual.max(1.0);
        if (pr as f64) < mean_item_est * 0.6 {
            score += 16.0 * (1.0 - pr / (mean_item_est * 0.6)) * (progress - 0.5);
        }
    }

    // Exact-fill chain reward.
    if !is_new_bin && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) <= mean_residual * 0.35 && after > 0 {
            score -= 12.0 * (1.0 - after as f64 / (mean_residual * 0.35).max(1.0)) * (0.5 + progress);
        }
    }

    // Awkward-dead-space squeeze in open bins (refined: sharper, earlier onset).
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let nf = next_item_size as f64;
        let frac = pr / nf;
        if frac > 0.12 && frac < 0.88 {
            let depth = 1.0 - (frac - 0.12).abs() / 0.38;
            score += 11.0 * depth.max(0.0) * (0.6 + progress);
        }
    }

    // MUTATION: competition-aware squeeze — when several open bins fit the item,
    // prefer the one whose post-residual exactly chains the next item; otherwise
    // penalize bins whose residual barely exceeds the item (tiny slivers).
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 {
        let slack = bin_residual.saturating_sub(item_size) as f64;
        let nf = next_item_size as f64;
        if slack >= nf {
            let chain_slack = slack - nf;
            if chain_slack <= 1.0 {
                score -= 14.0 * (1.0 - progress);
            } else if chain_slack < nf * 0.2 {
                score += 7.0 * (1.0 - chain_slack / (nf * 0.2)) * (0.4 + progress);
            }
        } else {
            // This open bin can't host the next item: mild penalty grows with fit competition.
            score += 5.0 * ((fitting_bins_count - 1) as f64).ln().max(0.0) * (0.5 + progress);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
