                score -= 14.0 * (1.0 - progress) * ((item_size as f64 / cap) - 0.55) / 0.45;
            }
        }
        // MUTATION: pair-compatibility of fresh bin with the mean residual —
        // a fresh bin whose post-chain residual sits near the mean residual is
        // reusable by future items; reward that alignment.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let align = 1.0 - ((chain_left - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 10.0 * align * (0.4 + 0.6 * progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    if !is_new_bin && post_residual == 0 {
        score -= 60.0;
    }

    if !is_new_bin && post_residual > 0 && post_residual <= 3 {
        score -= 35.0 * (1.0 - pr / 4.0);
