        let dev = (norm_pr - mean_norm).abs();
        if dev > 0.18 {
            score += 18.0 * (dev - 0.18) * progress;
        }
    }

    // Dead-space productivity check.
    if !is_new_bin && post_residual > 0 && progress > 0.5 {
        let mean_item_est = mean_residual.max(1.0);
        if pr < mean_item_est * 0.6 {
            score += 16.0 * (1.0 - pr / (mean_item_est * 0.6)) * (progress - 0.5);
        }
    }

    // Stranded-slack compaction: small unusable dead space is the dominant
    // waste source; escalate quadratically late so slivers get filled first.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_ratio = pr / cap;
        if dead_ratio > 0.10 {
            score += 22.0 * (dead_ratio - 0.10) * (dead_ratio - 0.10) * cap
                * (0.4 + progress) * (1.0 + mean_norm);
        }
        if pr < 3.0 {
            score += 14.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 38): high-dead-space squeeze — residuals that are dead yet
    // exceed half the next item size are the most recoverable waste; push
    // selection away from them progressively.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let frac = pr / nf;
        if frac > 0.5 {
            score += 14.0 * (frac - 0.5) * (0.3 + progress);
        }
    }

    // MUTATION (gen 38): perfect-dead-space elimination — tiny post-placement
    // residual essentially closes the bin; reward scaled by open-bin pressure.
    if !is_new_bin && post_residual > 0 && norm_pr < 0.03 && open_bins_count > 3 {
        score -= 9.0 * (1.0 - norm_pr / 0.03) * (0.6 + progress);
    }

    // MUTATION (gen 38): residual-chain divisibility refinement — post residual
    // an exact multiple of next item keeps the bin productive.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after % next_item_size == 0 {
            score -= 7.0 * (1.0 - progress);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

