    if !is_new_bin && post_residual == 0 && open_bins_count > 4 {
        score -= 8.0 * ((open_bins_count - 4) as f64).ln().max(0.0) * progress;
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

