            if chain_left >= mean_residual * 0.85 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        // Late stream with many open bins — consolidation pressure.
        if progress > 0.7 && open_bins_count > 6 {
            score += 10.0 * (open_bins_count as f64).ln() * (progress - 0.7) / 0.3;
        }
        // Mid-stream: avoid fresh bins when open bins fit with small dead space.
        if fitting_bins_count > 0 && progress > 0.3 && item_size as f64 >= 0.25 * cap {
            score += 14.0 * (progress - 0.3) / 0.7;
        }
        // Anti-fresh guard when open bins are already tight (mean residual small).
        if fitting_bins_count > 0 && progress > 0.15 && mean_norm < 0.2 {
            score += 12.0 * (0.2 - mean_norm) * (0.5 + progress);
        }
        // Residual-variance-aware fresh-bin guard.
        if fitting_bins_count > 0 && progress > 0.25 {
            let spread = (mean_norm - 0.5).abs();
            if spread < 0.25 {
                score += 16.0 * (0.25 - spread) * progress;
            }
        }
        // Triple-chain lookahead.
        if next_item_size > 0 && progress < 0.55 {
            let two = item_size + next_item_size;
            if two < bin_capacity {
                let third_left = bin_capacity - two;
                if (third_left as f64) >= mean_residual * 0.5 {
                    score -= 14.0 * (1.0 - progress) * (1.0 - third_left as f64 / cap);
                }
            }
        }
        // Dead-space-ratio-driven fresh-bin suppression.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let dead_after = (bin_residual.saturating_sub(item_size)) as f64;
            let dead_frac = dead_after / cap;
            if dead_frac > 0.45 {
                score -= 10.0 * (dead_frac - 0.45) * (1.0 - progress);
            } else if dead_frac > 0.05 {
                score += 20.0 * dead_frac * (0.4 + progress);
            }
        }
        // Fresh-bin quadratic chain quality — avoid awkward middle zone.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let mid_lo = 0.05 * cap;
            let mid_hi = (mean_residual * 0.9).max(mid_lo + 1.0);
            if chain_left > mid_lo && chain_left < mid_hi {
                let depth = 1.0 - (chain_left - mid_lo) / (mid_hi - mid_lo);
                score += 16.0 * depth * (0.5 + progress);
            }
        }
        // Item-size-aware fresh-bin trigger (reinforced): when the current item is
        // large relative to capacity and no open bin leaves a tight remainder,
        // opening a fresh bin early preserves small open residuals for small items.
        if fitting_bins_count > 0 && item_size as f64 > 0.55 * cap {
            let tight_open = if bin_residual >= item_size {
                ((bin_residual - item_size) as f64) < 0.08 * cap
            } else {
                false
            };
            if !tight_open && progress < 0.75 {
                score -= 16.0 * (1.0 - progress) * ((item_size as f64 / cap) - 0.55) / 0.45;
            }
        }
        // Pair-compatibility of fresh bin with the mean residual.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let align = 1.0 - ((chain_left - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 10.0 * align * (0.4 + 0.6 * progress);
            }
        }
        // Fresh-bin chain divisibility — multi-item chain potential.
        if next_item_size > 1 && item_size + next_item_size <= bin_capacity {
            let chain_left = bin_capacity - item_size - next_item_size;
            let rem = chain_left % next_item_size;
            if rem == 0 && chain_left > 0 {
                score -= 20.0 * (1.0 - 0.5 * progress);
            } else if rem <= 2 {
                score -= 8.0 * (1.0 - 0.5 * progress);
            }
        }
        // MUTATION (gen 39): fresh-bin harvest — when opening a fresh bin for a
        // large item would strand open residuals that can still host the next
        // item, reward it; but if the next item is small and could fill a
        // stranded residual, penalize the fresh bin (consolidation bias).
        if fitting_bins_count > 0 && next_item_size > 0 {
            let strandable = open_bins_count as f64;
            if nf <= 0.2 * cap && progress > 0.2 {
                score += 8.0 * (strandable.ln().max(0.0)) * (1.0 - progress);
            } else if nf > 0.4 * cap {
                score -= 6.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 39): fresh-bin waste ceiling — a fresh bin whose
        // unavoidable post-chain dead space exceeds the mean residual by a wide
        // margin is a poor investment; penalize proportionally.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            if chain_left > mean_residual * 1.6 && chain_left < nf {
                score += 14.0 * (chain_left / cap) * (0.5 + progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    if !is_new_bin && post_residual == 0 {
        score -= 60.0;
    }

    if !is_new_bin && post_residual > 0 && post_residual <= 3 {
        score -= 35.0 * (1.0 - pr / 4.0);
        score -= 20.0 * progress * (1.0 - pr / 4.0);
    }

    // Two-step lookahead in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let af = after as f64;
        if af >= 0.5 * nf && af <= 0.9 * cap {
            score -= 10.0 * (1.0 - af / cap) * (0.5 + progress);
        }
    }

    // Divisibility-aware residual shaping.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 6.0 * (1.0 - norm_pr) * (0.5 + progress);
        } else if next_item_size - rem <= 2 {
            score += 5.0 * progress;
        }
    }

    // Variance-targeting squeeze.
    if !is_new_bin {
        let dev = (norm_pr - mean_norm).abs();
        if dev > 0.18 {
            score += 18.0 * (dev - 0.18) * progress;
        }
    }

    // Dead-space ratio guard: residual that can never host a mean-sized item.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = 1.0 - pr / nf;
        score += 10.0 * dead_frac * dead_frac * (0.4 + progress);
    }

    // Dead-space productivity check.
    if !is_new_bin && post_residual > 0 && progress > 0.5 {
        let mean_item_est = mean_residual.max(1.0);
        if pr < mean_item_est * 0.6 {
            score += 16.0 * (1.0 - pr / (mean_item_est * 0.6)) * (progress - 0.5);
        }
    }

    // Exact-fill chain reward.
    if !is_new_bin && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) <= mean_residual * 0.35 && after > 0 {
            score -= 12.0 * (1.0 - after as f64 / (mean_residual * 0.35).max(1.0)) * (0.5 + progress);
        }
    }

    // Awkward-dead-space squeeze in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let frac = pr / nf;
        if frac > 0.15 && frac < 0.85 {
            let depth = 1.0 - (frac - 0.15).abs() / 0.35;
            score += 9.0 * depth.max(0.0) * (0.6 + progress);
        }
    }

    // Open-bin reusability shaping.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let band = ((pr - nf) / nf.max(1.0)).min(1.0);
        if band < 0.25 {
            score -= 7.0 * (0.25 - band) * (0.5 + progress);
        }
    }

    // High-dead-space open-bin squeeze.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let frac = pr / nf;
        if frac > 0.5 {
            score += 14.0 * (frac - 0.5) * (0.3 + progress);
        }
    }

    // Perfect-dead-space elimination.
    if !is_new_bin && post_residual > 0 && norm_pr < 0.03 && open_bins_count > 3 {
        score -= 9.0 * (1.0 - norm_pr / 0.03) * (0.6 + progress);
    }

    // Residual-chain divisibility refinement.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after % next_item_size == 0 {
            score -= 7.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 39): residual-harvest prioritization — among open bins that
    // fit the item, prefer the one whose residual most closely matches a
    // plausible future item (near mean residual), reducing stranded slivers.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let harvest = 1.0 - ((pr - mean_residual) / cap).abs() * 6.0;
        if harvest > 0.0 {
            score -= 6.0 * harvest * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 39): near-closure bonus strengthening — bins left with
    // residual below 2% of capacity are effectively closed; deepen the reward
    // when many bins remain open to consolidate stream length.
    if !is_new_bin && post_residual > 0 && norm_pr < 0.02 && open_bins_count > 2 {
        score -= 12.0 * (1.0 - norm_pr / 0.02) * (0.4 + 0.6 * progress);
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
