        }
    }

    // Variance-targeting squeeze.
    if !is_new_bin {
        let dev = (norm_pr - mean_norm).abs();
        if dev > 0.18 {
            score += 18.0 * (dev - 0.18) * progress;
        }
    }

    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);

        // Two-step fresh-bin chain quality.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            if leftover <= 2.0 {
                score -= 30.0 * (1.0 - progress);
            }
            if leftover <= 4.0 {
                score -= 35.0 * (1.0 - 0.5 * progress);
            } else if leftover <= 0.15 * cap {
                score -= 18.0 * (1.0 - leftover / (0.15 * cap)) * (1.0 - 0.5 * progress);
            }
            if leftover >= nf {
                score -= 15.0 * (1.0 - progress);
            }
            // Chain divisibility: perfect multi-item chain.
            let cl = bin_capacity - item_size - next_item_size;
            if cl > 0 && next_item_size > 1 {
                let rem = cl % next_item_size;
                if rem == 0 {
                    score -= 20.0 * (1.0 - 0.5 * progress);
                } else if rem <= 2 {
                    score -= 8.0 * (1.0 - 0.5 * progress);
                }
            }
            // Chain-left alignment with mean residual.
            let align = 1.0 - ((leftover - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 10.0 * align * (0.4 + 0.6 * progress);
            }
            // Avoid awkward middle zone.
            let mid_lo = 0.05 * cap;
            let mid_hi = (mean_residual * 0.9).max(mid_lo + 1.0);
            if leftover > mid_lo && leftover < mid_hi {
                let depth = 1.0 - (leftover - mid_lo) / (mid_hi - mid_lo);
                score += 16.0 * depth * (0.5 + progress);
            }
        }

        // Fresh-bin residual near-perfectly matching next item: open eagerly.
        if next_item_size > 0 && item_size < bin_residual {
            let fresh_left = bin_residual - item_size;
            if fresh_left >= next_item_size && (fresh_left - next_item_size) <= 3 {
                score -= 40.0 * (1.0 - progress);
            }
        }

        // Capacity divisibility by next item.
        if next_item_size > 0 {
            let rem = bin_capacity % next_item_size;
            if rem == 0 {
                score -= 22.0 * (1.0 - 0.4 * progress);
            } else if rem <= 3 {
                score -= 10.0 * (1.0 - 0.4 * progress);
            }
        }

        // Large item into nearly-fitting open bin: prefer that over fresh bin.
        if item_size as f64 > 0.7 * cap && fitting_bins_count > 0 {
            let best_possible = bin_residual.saturating_sub(item_size);
            if best_possible > 0 && (best_possible as f64) < 0.15 * cap {
                score -= 20.0;
            }
        }

        // MUTATION: item-size-aware fresh-bin trigger.
        if fitting_bins_count > 0 && item_size as f64 > 0.55 * cap && progress < 0.75 {
            let tight_open = bin_residual >= item_size
                && ((bin_residual - item_size) as f64) < 0.08 * cap;
            if !tight_open {
                score -= 14.0 * (1.0 - progress) * ((item_size as f64 / cap) - 0.55) / 0.45;
            }
        }

        // Late stream: consolidation pressure.
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        if progress > 0.7 && open_bins_count > 6 {
            score += 10.0 * (open_bins_count as f64).ln() * (progress - 0.7) / 0.3;
        }

        // Mid-stream: avoid fresh bins when open bins fit with small dead space.
        if fitting_bins_count > 0 && progress > 0.3 && item_size as f64 >= 0.25 * cap {
            score += 14.0 * (progress - 0.3) / 0.7;
        }

        // Anti-fresh guard when open bins are already tight.
        if fitting_bins_count > 0 && progress > 0.15 && mean_norm < 0.2 {
            score += 12.0 * (0.2 - mean_norm) * (0.5 + progress);
        }

        // Dead-space-ratio-driven fresh-bin suppression.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let dead_after = (bin_residual.saturating_sub(item_size)) as f64;
            let dead_frac = dead_after / cap;
            if dead_frac > 0.45 {
                score -= 10.0 * (dead_frac - 0.45) * (1.0 - progress);
            } else if dead_frac > 0.05 {
                score += 20.0 * dead_frac * (0.4 + progress);
            }
        }

        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Open-bin closure bonuses.
    if !is_new_bin && post_residual == 0 {
        score -= 60.0;
    }
    if !is_new_bin && post_residual > 0 && post_residual <= 3 {
        score -= 35.0 * (1.0 - pr / 4.0);
        score -= 20.0 * progress * (1.0 - pr / 4.0);
    }

    // Two-step lookahead in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after >= 0.5 * nf && after <= 0.9 * cap {
            score -= 10.0 * (1.0 - after / cap) * (0.5 + progress);
        }
    }

    // Divisibility-aware residual shaping.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 6.0 * (1.0 - norm_pr) * (0.5 + progress);
        } else if next_item_size - rem <= 2 {
            score += 5.0 * progress;
        }
    }

    // Dead-space productivity check late in stream.
    if !is_new_bin && post_residual > 0 && progress > 0.5 {
        let mean_item_est = mean_residual.max(1.0);
        if pr < mean_item_est * 0.6 {
            score += 16.0 * (1.0 - pr / (mean_item_est * 0.6)) * (progress - 0.5);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;
    let mean_norm = mean_residual / cap;
    let nf = next_item_size as f64;

    // Base: wasted space with super-linear residual pressure.
    let mut score = pr + 14.0 * norm_pr * norm_pr * cap;

    // Progress-coupled residual pressure.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Smooth reward for near-perfect fits.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chaining with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = nf / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let leftover_after = post_residual - next_item_size;
            if leftover_after <= 2 {
                score -= 25.0;
            } else if leftover_after <= 6 {
                score -= 8.0 * (1.0 - (leftover_after - 2) as f64 / 4.0);
            }
            if leftover_after > 0 && (leftover_after as f64) < 0.5 * nf {
                score += 4.0 * (1.0 - leftover_after as f64 / nf);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / nf.max(1.0);
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
        }
    }

    // Mean-residual coupling: below-mean bins are compact.
    score += 15.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Dead-space ratio penalty (tightened threshold).
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        if norm_pr > 0.22 {
            score += 32.0 * (norm_pr - 0.22) * (0.5 + progress) * (1.0 + mean_norm);
        }
    }

    // Multi-fit competition.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 {
        let mismatch = (pr - nf).abs() / cap;
        let comp = ((fitting_bins_count - 1) as f64).ln().max(0.0);
        score += 6.0 * mismatch * comp;
        if pr == nf {
            score -= 5.0 * comp;
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            if leftover <= 2.0 {
                score -= 30.0 * (1.0 - progress);
            }
            if leftover <= 4.0 {
                score -= 35.0 * (1.0 - 0.5 * progress);
            } else if leftover <= 0.15 * cap {
                score -= 18.0 * (1.0 - leftover / (0.15 * cap)) * (1.0 - 0.5 * progress);
            }
            if leftover >= nf {
