        // Fresh-bin quadratic chain quality — avoid awkward middle zone.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let mid_lo = 0.05 * cap;
            let mid_hi = (mean_residual * 0.9).max(mid_lo + 1.0);
            if chain_left > mid_lo && chain_left < mid_hi {
                let depth = 1.0 - (chain_left - mid_lo) / (mid_hi - mid_lo);
                score += 16.0 * depth * (0.5 + progress);
            }
        }
        // MUTATION (gen42, refined): item-size-aware fresh-bin trigger with
        // residual-value weighting — preserve open residuals whose size is
        // reusable by the upcoming item stream; open fresh bins for large
        // items only when the resulting leftover would be low-value.
        if fitting_bins_count > 0 && item_size as f64 > 0.55 * cap {
            let leftover_if_open = bin_residual.saturating_sub(item_size);
            let tight_open = bin_residual >= item_size
                && ((leftover_if_open as f64) < 0.08 * cap
                    || (next_item_size > 0 && leftover_if_open >= next_item_size
                        && (leftover_if_open - next_item_size) <= 4));
            if !tight_open && progress < 0.8 {
                let size_weight = ((item_size as f64 / cap) - 0.55) / 0.45;
                score -= 16.0 * (1.0 - progress) * size_weight;
            }
        }
        // MUTATION: pair-compatibility alignment with mean residual.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
