    if !is_new_bin && post_residual > 0 && norm_pr < 0.03 && open_bins_count > 3 {
        score -= 9.0 * (1.0 - norm_pr / 0.03) * (0.6 + progress);
    }

    // Residual-chain divisibility refinement.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after % next_item_size == 0 {
            score -= 7.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen42): double-dead guard — penalize open bins whose leftover
    // after this item can host neither the next item nor a mean-sized item,
    // i.e. truly stranded waste, more aggressively late in the stream.
    if !is_new_bin && next_item_size > 0 && post_residual > 0
        && post_residual < next_item_size
        && (pr as f64) < mean_residual.max(1.0) * 0.5 {
        score += 12.0 * (1.0 - pr / (mean_residual.max(1.0) * 0.5)) * (0.5 + progress);
    }

    // MUTATION (gen42): reusable-residual conservation — when the leftover
    // after placing this item exactly matches a plausible future item size
    // (near the next item or a divisor-style multiple), reward keeping the
    // bin alive rather than scattering residual capacity.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let af = after as f64;
        if af > 0.0 && af <= 0.2 * cap && (af - nf).abs() <= 2.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

