        // residuals for small items by opening fresh bins for large items.
        if fitting_bins_count > 0 && item_size as f64 > 0.55 * cap {
            let tight_open = bin_residual >= item_size
                && (((bin_residual - item_size) as f64) < 0.08 * cap);
            if !tight_open && progress < 0.75 {
                score -= 14.0 * (1.0 - progress) * ((item_size as f64 / cap) - 0.55) / 0.45;
