        // usability — if open residuals are mostly too small to host the
        // average item, opening a fresh bin is cheaper than dumping into a
        // nearly-full bin. Refined threshold from 0.25 to 0.20 and
        // strengthened mid-stream weight.
        if fitting_bins_count > 0 && mean_norm < 0.20 {
            score += (0.20 - mean_norm) * 90.0 * (0.35 + 0.65 * progress);
        }
        // MUTATION: residual-fragmentation guard — penalize opening a fresh
        // bin when several open bins can still host the next item too
        // (avoid scattering small residuals across many half-empty bins).
