        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score -= 10.0 * scarcity * (1.0 - pr / 7.0) * (0.5 + progress);
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

