    // smaller than the next item and below a fraction of the mean residual is
    // effectively dead space; penalize choosing it over better fits.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        if (pr as f64) < 0.35 * mean_residual.max(1.0) && fitting_bins_count > 1 {
