        }
    }

    // NEW: triple-lookahead compaction — reward open bins whose residual can
    // still host both the next item and a follow-up mean-sized item.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after >= mean_residual * 0.8 {
            score -= 9.0 * (1.0 - after / cap) * (0.4 + 0.6 * progress);
        }
    }

    // NEW: mid-stream consolidation — prefer bins whose post-residual stays
