    if !is_new_bin && post_residual > 0 && progress > 0.3 {
        let dev_after = ((pr - mean_residual) / cap).abs();
        if dev_after < 0.06 {
            score -= 8.0 * (0.06 - dev_after) / 0.06 * (0.4 + progress);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

