        if fitting_bins_count > 0 && next_item_size > 0 {
            let dead_after = (bin_residual.saturating_sub(item_size)) as f64;
            let dead_frac = dead_after / cap;
            if dead_frac > 0.45 {
                score -= 10.0 * (dead_frac - 0.45) * (1.0 - progress);
            } else if dead_frac > 0.05 {
                score += 20.0 * dead_frac * (0.4 + progress);
            }
        }
        // Fresh-bin quadratic chain quality — avoid awkward middle zone.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let mid_lo = 0.05 * cap;
            let mid_hi = (mean_residual * 0.9).max(mid_lo + 1.0);
            if chain_left > mid_lo && chain_left < mid_hi {
                let depth = 1.0 - (chain_left - mid_lo) / (mid_hi - mid_lo);
                score += 16.0 * depth * (0.5 + progress);
            }
        }
        // MUTATION (kept): item-size-aware fresh-bin trigger.
        if fitting_bins_count > 0 && item_size as f64 > 0.55 * cap {
            let tight_open = bin_residual >= item_size
                && (((bin_residual - item_size) as f64) < 0.08 * cap);
            if !tight_open && progress < 0.75 {
                score -= 14.0 * (1.0 - progress) * ((item_size as f64 / cap) - 0.55) / 0.45;
            }
        }
        // MUTATION (kept): pair-compatibility alignment with mean residual.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            let align = 1.0 - ((chain_left - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 10.0 * align * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION (kept): fresh-bin chain divisibility — perfect multi-item chains.
        if next_item_size > 1 && item_size + next_item_size <= bin_capacity {
            let chain_left = bin_capacity - item_size - next_item_size;
            let rem = chain_left % next_item_size;
            if rem == 0 && chain_left > 0 {
                score -= 20.0 * (1.0 - 0.5 * progress);
            } else if rem <= 2 {
                score -= 8.0 * (1.0 - 0.5 * progress);
            }
        }
        // MUTATION (kept): prefer fresh bins when all open fits leave bad dead space.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_dead = (bin_capacity - item_size) as f64;
            if fresh_dead < nf && (fresh_dead / cap) < 0.12 {
                score -= 25.0 * (1.0 - progress);
            }
        }
        // MUTATION (kept): fresh-bin chain-harvest refinement.
        if next_item_size > 1 && item_size + next_item_size <= bin_capacity && progress > 0.2 && progress < 0.8 {
            let chain_left = bin_capacity - item_size - next_item_size;
            if chain_left > 0 {
                let rem2 = chain_left % (next_item_size.min(10));
                if rem2 == 0 {
                    score -= 12.0 * (1.0 - (progress - 0.2).abs().max(0.0) / 0.6);
                }
            }
        }
        // MUTATION (kept): dead-space recovery pressure.
        if fitting_bins_count > 0 && next_item_size > 0 && open_bins_count > 4 {
            let chain_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if chain_left > 0.3 * cap {
                score += 20.0 * (chain_left / cap - 0.3) * ((open_bins_count - 4) as f64).min(8.0) * 0.25;
            }
        }
        // MUTATION (new): fresh-bin harvest-depth gradient — reward fresh bins whose
        // chain residual after the next item can still host a *small* item, i.e.
        // residual stays productive rather than stranded, with tighter reward the
        // closer it lands to a perfect zero residual.
        if fitting_bins_count > 0 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_left = (bin_capacity - item_size - next_item_size) as f64;
            if chain_left > 0.0 {
                let productivity = (chain_left / mean_residual.max(1.0)).min(1.0);
                score -= 9.0 * (1.0 - productivity) * (0.6 + 0.4 * progress);
            }
        }
        // MUTATION (new): open-bin scarcity trigger — when very few open bins can
        // host the *next* item after this placement, a fresh bin that preserves
        // next-item fit is strongly preferred to avoid a forced future open.
        if fitting_bins_count > 0 && next_item_size > 0 && open_bins_count > 2 {
            let future_fit = (bin_residual.saturating_sub(item_size)) >= next_item_size;
            if !future_fit {
                let fresh_future_fit = (bin_capacity - item_size) >= next_item_size;
                if fresh_future_fit {
                    score -= 16.0 * (1.0 - progress) * (1.0 / fitting_bins_count as f64);
