        }
    }

    // MUTATION (kept): compaction pull toward near-zero post-residual.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after < 0.04 * cap {
            score -= 11.0 * (1.0 - after / (0.04 * cap)) * (0.3 + progress);
        }
    }

    // MUTATION (new): harvest-efficiency gradient in open bins — reward bins whose
    // post-residual, after hosting the next item, remains a productive fraction of
