    // dead band. Fine-tunes the parent's residual-space weakness by targeting the
    // mid-band waste directly rather than only near-zero residuals.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let harvest = after / mean_residual.max(1.0);
