    }

    // Dead-space ratio guard: residual that can never host a mean-sized item.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = 1.0 - pr / nf;
        score += 10.0 * dead_frac * dead_frac * (0.4 + progress);
    }

    // Dead-space productivity check.
    if !is_new_bin && post_residual > 0 && progress > 0.5 {
        let mean_item_est = mean_residual.max(1.0);
        if pr < mean_item_est * 0.6 {
            score += 16.0 * (1.0 - pr / (mean_item_est * 0.6)) * (progress - 0.5);
        }
    }

    // Exact-fill chain reward.
    if !is_new_bin && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) <= mean_residual * 0.35 && after > 0 {
            score -= 12.0 * (1.0 - after as f64 / (mean_residual * 0.35).max(1.0)) * (0.5 + progress);
        }
    }

    // Awkward-dead-space squeeze in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let frac = pr / nf;
        if frac > 0.15 && frac < 0.85 {
            let depth = 1.0 - (frac - 0.15).abs() / 0.35;
            score += 9.0 * depth.max(0.0) * (0.6 + progress);
        }
    }

    // Open-bin reusability shaping — residual stays within a small band of next item.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let band = ((pr - nf) / nf.max(1.0)).min(1.0);
        if band < 0.25 {
            score -= 7.0 * (0.25 - band) * (0.5 + progress);
        }
    }

    // High-dead-space open-bin squeeze — half-dead residuals are recoverable waste.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let frac = pr / nf;
        if frac > 0.5 {
            score += 14.0 * (frac - 0.5) * (0.3 + progress);
        }
    }

    // Perfect-dead-space elimination — near-closed bins get filled first.
    if !is_new_bin && post_residual > 0 && norm_pr < 0.03 && open_bins_count > 3 {
        score -= 9.0 * (1.0 - norm_pr / 0.03) * (0.6 + progress);
    }

    // Residual-chain divisibility refinement.
    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after % next_item_size == 0 {
            score -= 7.0 * (1.0 - progress);
        }
    }

    // MUTATION (kept): open-bin crowding penalty.
    if !is_new_bin && open_bins_count > 8 {
        score += 2.5 * (open_bins_count as f64 - 8.0).min(12.0) * (0.3 + progress);
    }

    // MUTATION (kept): strong preference for reusable post-residuals.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let reusability = 1.0 - (pr - nf) / cap;
        score -= 6.0 * reusability * (1.0 / fitting_bins_count.max(1) as f64);
    }

    // MUTATION (kept): stranded dead-space penalty.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded > nf * 0.4 && stranded < mean_residual * 0.8 {
            score += 8.0 * (1.0 - stranded / (mean_residual * 0.8)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (kept): compaction pull toward zero post-residual.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after < 0.04 * cap {
            score -= 11.0 * (1.0 - after / (0.04 * cap)) * (0.3 + progress);
        }
    }

    // MUTATION (new): harmonic-fill targeting — reward open bins whose
    // post-residual, after hosting this item, can be tiled by the next item
    // size with zero or tiny slack; this drives residual variance down and
    // converts near-dead residuals into exact multi-item fills.
    if !is_new_bin && next_item_size > 1 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        let tiles = after / next_item_size;
        let slack = after - tiles * next_item_size;
        if tiles >= 1 && slack == 0 {
            score -= 14.0 * (1.0 - (tiles as f64).min(4.0) / 4.0) * (0.4 + 0.6 * progress);
        } else if tiles >= 1 && slack <= 2 {
            score -= 6.0 * (1.0 - slack as f64 / 3.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (new): dead-space budget — when few bins compete, tolerate a
    // small residual; when many compete, punish any residual above the
    // mean-scaled threshold, sharpening selection among equals.
    if !is_new_bin && next_item_size > 0 && fitting_bins_count > 2 {
        let threshold = mean_norm * cap * 0.6;
        if pr > threshold {
            score += 5.0 * ((pr - threshold) / cap) * ((fitting_bins_count - 2) as f64).min(5.0) * (0.5 + progress);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
