    if !is_new_bin && next_item_size > 0 && nf > 0.6 * cap && progress < 0.5 {
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - progress);
        }
    }

    // MUTATION (new): open-bin count-aware consolidation — with many open bins,
