    if is_new_bin && fitting_bins_count > 0 && next_item_size > 0 {
        // approximate: any open fit that would be near-perfect beats a fresh bin
        score += 30.0 * (1.0 - progress);
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

