    // Stranded dead-space refinement.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded > nf * 0.4 && stranded < mean_residual * 0.8 {
            score += 8.0 * (1.0 - stranded / (mean_residual * 0.8)) * (0.4 + 0.6 * progress);
        }
    }

    // Compaction pull — reward near-zero post-residual after hosting next item.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after < 0.04 * cap {
            score -= 11.0 * (1.0 - after / (0.04 * cap)) * (0.3 + progress);
        }
    }

    // MUTATION: harmonic-class fit quality — penalize dumping large-class items
    // into nearly-half-empty bins late in the stream.
    let quarter = (bin_capacity / 4).max(1);
    let item_class = item_size / quarter;
    if !is_new_bin && item_class >= 3 && norm_pr > 0.4 {
        score += 10.0 * (norm_pr - 0.4) * (0.5 + progress);
    }

    // MUTATION: early-stream large-item reserve — keep roomy bins for big items.
    if !is_new_bin && next_item_size > 0 && nf > 0.6 * cap && progress < 0.5 {
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - progress);
        }
    }

    // MUTATION: open-bin count-aware consolidation.
    if !is_new_bin && open_bins_count > 5 {
        score += 0.15 * ((open_bins_count - 5) as f64).min(10.0) * pr;
    }

    // MUTATION (new): dead-space guard — when this open bin cannot host the next
    // item and would strand a mid-range dead sliver, escalate the penalty
    // quadratically so poor-fit bins lose priority against fresh-bin chains.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_frac = 1.0 - pr / nf;
        score += 10.0 * dead_frac * dead_frac * (0.4 + progress);
        if dead_frac > 0.6 && progress > 0.4 {
            score += 6.0 * (dead_frac - 0.6) * (progress - 0.4) * cap * 0.1;
        }
    }

    // MUTATION (new): dual-fit squeeze — when multiple open bins fit, prefer the
    // one whose post-residual best matches the mean residual (keeps average
    // residual class consistent and leaves uniformly reusable bins).
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let align = (after - mean_residual).abs() / cap;
        score += 5.0 * align * (0.3 + progress);
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;
    let mean_norm = mean_residual / cap;
    let nf = next_item_size as f64;

    // Base: wasted space with super-linear punishment of large residuals.
    let mut score = pr + 14.0 * norm_pr * norm_pr * cap;

    // Progress-coupled residual pressure.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Smooth reward for near-perfect fits.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chaining with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = nf / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let leftover_after = post_residual - next_item_size;
            if leftover_after <= 2 {
