    let quarter = (bin_capacity / 4).max(1);
    let item_class = item_size / quarter;
    if !is_new_bin && item_class >= 3 && norm_pr > 0.4 {
        score += 10.0 * (norm_pr - 0.4) * (0.5 + progress);
    }

    // Early-stream large-item reserve.
    if !is_new_bin && next_item_size > 0 && nf > 0.6 * cap && progress < 0.5 {
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Open-bin count-aware consolidation.
    if !is_new_bin && open_bins_count > 5 {
        score += 0.15 * ((open_bins_count - 5) as f64).min(10.0) * pr;
    }

    // MUTATION (gen 45): residual-band homogenization — with many open bins, steer
    // placements toward bins whose post-residual lands near the stream's mean
    // residual, shrinking residual variance and enabling later tight fills.
    if !is_new_bin && next_item_size > 0 && open_bins_count > 3 {
        let band_align = ((pr - mean_residual) / cap).abs();
        if band_align < 0.06 {
            score -= 9.0 * (1.0 - band_align / 0.06) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 45): dead-space floor sweep — when the item's fit leaves a
    // residual that is too small for the next item but non-trivial, penalize
    // proportionally harder mid-stream to avoid accumulating stranded slivers.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let sliver = pr / nf.max(1.0);
        if sliver < 0.35 && progress > 0.2 {
            score += 13.0 * (0.35 - sliver) * (progress - 0.2) / 0.8;
        }
    }

    // MUTATION (gen 45): fresh-bin last-quarter suppression — late in the stream,
