    if is_new_bin && fitting_bins_count > 0 && progress > 0.75 {
        let perfect = next_item_size > 0 && item_size + next_item_size == bin_capacity;
        if !perfect {
            score += 20.0 * (progress - 0.75) / 0.25;
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

