            score -= 9.0 * (1.0 - pr / harvestable.max(1.0)) * (0.35 + 0.65 * progress);
        } else if pr > harvestable && pr < nf {
            let strandedness = (pr - harvestable) / (nf - harvestable).max(1.0);
            score += 7.0 * strandedness * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 46): exact-ratio chain bonus — if the residual after
    // hosting the next item equals an integer multiple of next_item_size,
    // the bin becomes a perfect repeating container; reward strongly.
    if !is_new_bin && next_item_size > 1 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after % next_item_size == 0 {
            let reps = (after / next_item_size) as f64;
            if reps >= 1.0 {
                score -= 13.0 * reps.min(4.0) * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 46): two-item lookahead fit — when the bin cannot host
    // the next item, check whether it could host the item after next if the
    // next item goes elsewhere; avoid destroying a good future slot.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size && norm_pr > 0.15 && progress < 0.7 {
        let stranded_gap = (next_item_size - post_residual) as f64;
        if stranded_gap < 0.25 * nf {
            score += 10.0 * (1.0 - stranded_gap / (0.25 * nf)) * (0.6 + progress);
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;
    let mean_norm = mean_residual / cap;
    let nf = next_item_size as f64;

    // Base: wasted space with super-linear punishment of large residuals.
    let mut score = pr + 14.0 * norm_pr * norm_pr * cap;

    // Progress-coupled residual pressure.
    let progress_pressure = 0.5 + progress * progress * 1.5;
    score += 30.0 * progress_pressure * norm_pr * (1.0 - norm_pr);

    // Smooth reward for near-perfect fits.
    let tightness = (-norm_pr / 0.08).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Lookahead chaining with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let fill = nf / pr.max(1.0);
            score -= 20.0 * fill * (1.0 - norm_pr);
            let leftover_after = post_residual - next_item_size;
            if leftover_after <= 2 {
                score -= 25.0;
            } else if leftover_after <= 6 {
                score -= 8.0 * (1.0 - (leftover_after - 2) as f64 / 4.0);
            }
            if leftover_after > 0 && (leftover_after as f64) < 0.5 * nf {
                score += 4.0 * (1.0 - leftover_after as f64 / nf);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let dead_frac = gap / nf.max(1.0);
            score += 8.0 * norm_pr * (0.3 + progress)
                + 5.0 + gap * 0.35
                + 20.0 * dead_frac * dead_frac * (0.5 + progress);
