    // (e.g. cap/2, cap/3) fit best into bins whose residual matches them exactly;
    // penalize dumping large-class items into nearly-full bins late in stream.
    let quarter = (bin_capacity / 4).max(1);
    let item_class = item_size / quarter;
    if !is_new_bin && item_class >= 3 && norm_pr > 0.4 {
        score += 10.0 * (norm_pr - 0.4) * (0.5 + progress);
    }

    // MUTATION (new): early-stream large-item reserve — when a big item is coming,
    // keep at least one roomy bin open by penalizing filling the roomiest bin.
    if !is_new_bin && next_item_size > 0 && nf > 0.6 * cap && progress < 0.5 {
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - progress);
        }
    }

    // MUTATION (new): open-bin count-aware consolidation — with many open bins,
    // amplify the tightness reward to close bins rather than spread items.
    if !is_new_bin && open_bins_count > 5 {
        score += 0.15 * ((open_bins_count - 5) as f64).min(10.0) * pr;
    }

    // MUTATION (gen 46): residual-entropy shaping — residuals in the "dead zone"
    // (too small for the mean item yet too large to ignore) strand space forever.
    // Push bins either to near-zero post_residual or to residuals that can host
    // the mean-sized future item, reducing long-run dead-space variance.
    if !is_new_bin && next_item_size > 0 {
        let mean_item = mean_residual.max(1.0);
        if pr > 0.0 && pr < mean_item * 0.9 && pr > 0.06 * cap {
            let zone_depth = 1.0 - (pr - 0.06 * cap) / (mean_item * 0.9 - 0.06 * cap).max(1.0);
            score += 13.0 * zone_depth * (0.35 + 0.65 * progress) * (1.0 - 0.5 * mean_norm);
        }
        // Reward residuals that can still absorb a mean-sized item after this fill.
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= mean_item * 0.9 {
                score -= 9.0 * (1.0 - after / cap) * (0.4 + progress);
            }
        }
    }

    // MUTATION (gen 46): late-stream terminal-squeeze — as the stream ends, only
    // near-exact fits are worth keeping open; amplify exact-fill rewards and
    // penalize any leftover that cannot be closed by the next item.
    if !is_new_bin && progress > 0.75 {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0 * (progress - 0.75) / 0.25;
        } else if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.05 * cap {
                score += 18.0 * (progress - 0.75) / 0.25 * (after / cap);
            }
        }
    }

    // Early-stream waste tolerance.
    score *= 1.0 - 0.15 * progress;

    score
}

