        }
    }

    // Perfect-dead-space elimination.
    if !is_new_bin && post_residual > 0 && norm_pr < 0.03 && open_bins_count > 3 {
        score -= 9.0 * (1.0 - norm_pr / 0.03) * (0.6 + progress);
    }

    // Variance-targeting squeeze.
    if !is_new_bin {
        let dev = (norm_pr - mean_norm).abs();
        if dev > 0.18 {
            score += 18.0 * (dev - 0.18) * progress;
        }
    }

    // Harmonic-class fit quality: avoid dumping large-class items into roomy bins.
    if !is_new_bin && item_class >= 3 && norm_pr > 0.4 {
        score += 10.0 * (norm_pr - 0.4) * (0.5 + progress);
    }

    // Early-stream large-item reserve.
    if !is_new_bin && next_item_size > 0 && nf > 0.6 * cap && progress < 0.5 && post_residual < next_item_size {
        score += 12.0 * (1.0 - progress);
    }

    // Open-bin count-aware consolidation.
    if !is_new_bin && open_bins_count > 5 {
        score += 0.15 * ((open_bins_count - 5) as f64).min(10.0) * pr;
    }

    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 + open_pressure * (15.0 + 40.0 * progress) - 25.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = (bin_capacity - item_size - next_item_size) as f64;
            score -= 60.0 * (1.0 - progress)
                - 10.0 * (1.0 - leftover / cap) * (1.0 - progress);
            if leftover <= 2.0 {
                score -= 30.0 * (1.0 - progress);
            } else if leftover <= 4.0 {
                score -= 35.0 * (1.0 - 0.5 * progress);
            } else if leftover <= 0.15 * cap {
                score -= 18.0 * (1.0 - leftover / (0.15 * cap)) * (1.0 - 0.5 * progress);
            }
            if leftover >= nf {
                score -= 15.0 * (1.0 - progress);
            }
            // chain divisibility — perfect multi-item chains
            if next_item_size > 1 {
                let chain_left = bin_capacity - item_size - next_item_size;
                let rem = chain_left % next_item_size;
                if rem == 0 && chain_left > 0 {
                    score -= 20.0 * (1.0 - 0.5 * progress);
                } else if rem <= 2 {
                    score -= 8.0 * (1.0 - 0.5 * progress);
                }
            }
            // mid-zone chain quality — avoid awkward middle leftover
            let mid_lo = 0.05 * cap;
            let mid_hi = (mean_residual * 0.9).max(mid_lo + 1.0);
            if leftover > mid_lo && leftover < mid_hi {
                let depth = 1.0 - (leftover - mid_lo) / (mid_hi - mid_lo);
                score += 16.0 * depth * (0.5 + progress);
            }
            // pair-compatibility alignment with mean residual
            let align = 1.0 - ((leftover - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 10.0 * align * (0.4 + 0.6 * progress);
            }
        }
        if progress > 0.6 {
            score += 45.0 * (progress - 0.6) / 0.4;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress <= 0.6 && fitting_bins_count == 1 {
            score -= 18.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_dead = bin_residual.saturating_sub(next_item_size) as f64;
            if worst_dead > item_size as f64 {
                score -= 12.0 + 20.0 * (1.0 - progress);
            }
        }
        // Item-size-aware fresh-bin trigger.
        if fitting_bins_count > 0 && item_size as f64 > 0.55 * cap {
            let tight_open = bin_residual >= item_size
                && (((bin_residual - item_size) as f64) < 0.08 * cap);
            if !tight_open && progress < 0.75 {
                score -= 14.0 * (1.0 - progress) * ((item_size as f64 / cap) - 0.55) / 0.45;
            }
        }
        // Prefer fresh bins when all open fits leave bad dead space.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let fresh_dead = (bin_capacity - item_size) as f64;
            if fresh_dead < nf && (fresh_dead / cap) < 0.12 {
                score -= 25.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let dead_after = (bin_residual.saturating_sub(item_size)) as f64;
            let dead_frac = dead_after / cap;
            if dead_frac > 0.45 {
                score -= 10.0 * (dead_frac - 0.45) * (1.0 - progress);
            } else if dead_frac > 0.05 {
                score += 20.0 * dead_frac * (0.4 + progress);
            }
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    if !is_new_bin && post_residual == 0 {
        score -= 60.0;
    }

    if !is_new_bin && post_residual > 0 && post_residual <= 3 {
        score -= 35.0 * (1.0 - pr / 4.0) + 20.0 * progress * (1.0 - pr / 4.0);
    }

    // Two-step lookahead in open bins.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let af = after as f64;
        if af >= 0.5 * nf && af <= 0.9 * cap {
            score -= 10.0 * (1.0 - af / cap) * (0.5 + progress);
        }
    }

    // MUTATION (Gen 46): residual-class harvest — small residuals (< cap/8) are
    // only worth keeping if the next item can consume them; otherwise penalize
    // proportionally to how much capacity is stranded.
    if !is_new_bin && post_residual > 0 && norm_pr < 0.125 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 14.0 * (1.0 - norm_pr / 0.125);
        } else {
            score += 18.0 * (1.0 - norm_pr / 0.125) * (0.4 + progress);
        }
    }

    // MUTATION (Gen 46): late-stream consolidation — when few items remain,
    // amplify preference for bins that will end near-full regardless of lookahead.
    if progress > 0.75 {
        score += 20.0 * (progress - 0.75) / 0.25 * norm_pr;
    }

    // MUTATION (Gen 47): dead-space harvest gate — when the next item cannot
    // consume the leftover, punish bins whose post-residual falls into the
    // "awkward middle" zone (too big to ignore, too small to be reusable),
    // scaled by how much of the next item is stranded.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = nf - pr;
        let mid_zone = stranded > 0.3 * nf && stranded < 0.75 * nf;
        if mid_zone {
            score += 14.0 * (1.0 - (stranded - 0.3 * nf).abs() / (0.45 * nf)) * (0.5 + progress);
        }
        // Harvestable check: could the residual after this item still host a
        // typical small item? If not, penalize proportionally to the waste.
        let harvestable = pr >= mean_norm * cap * 0.5;
        if !harvestable && norm_pr > 0.15 {
            score += 10.0 * (norm_pr - 0.15) * (0.6 + progress);
        }
    }

    // MUTATION (Gen 47): best-fit sharpening — when several bins can host the
    // next item, prefer the one whose post-residual after that item is closest
    // to zero, using a quadratic pull that grows with competition.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = (post_residual - next_item_size) as f64;
        let comp = ((fitting_bins_count - 1) as f64).ln().max(0.0);
        score += 9.0 * (after / cap) * (after / cap) * comp * (0.5 + progress);
    }

    // MUTATION (Gen 47): fresh-bin chain-dead guard — open a new bin only if
    // the resulting fresh residual (after both items) is either tiny or at
    // least large enough for the mean-sized follow-up; middle-zone fresh
    // residuals get punished, near-perfect ones get rewarded.
    if is_new_bin && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
        let fresh_left = (bin_capacity - item_size - next_item_size) as f64;
        if fresh_left > 0.08 * cap && fresh_left < mean_residual.max(1.0) {
            score += 22.0 * (1.0 - fresh_left / mean_residual.max(1.0)) * (0.5 + progress);
        }
    }

    score
}
